/* C1 · topics 1–5 (format: see a2-part1.js). */
module.exports = [
  { title: 'Complex argument', lessons: [
    { t: ['Building an argument', 'Dalil qurish'],
      obj: ['Murakkab dalilni premissa, isbot va xulosa tuzilmasida quraysiz.', 'You will build a complex argument from premise, evidence and conclusion.'],
      ex: ['Dalil tuzilmasi: claim (da’vo) → premise (asos) → evidence (dalil) → warrant (nega dalil da’voni qo‘llaydi) → conclusion. Mantiqiy bog‘lovchilar: it follows that (shundan kelib chiqadiki), hence, thereby, by extension, given that, in light of. Dalil turlari: empirical (tajribaviy), statistical, anecdotal (hikoyaviy), expert opinion.\nNominalizatsiya: The rapid expansion of cities has led to… (Cities expand rapidly, so…). Avoid logical fallacies (mantiqiy xato): ad hominem, straw man, false dilemma, slippery slope. Aniqlik: Insofar as…, to the extent that…',  'Argument structure: claim → premise → evidence → warrant (why the evidence supports the claim) → conclusion. Logical connectors: it follows that, hence, thereby, by extension, given that, in light of. Types of evidence: empirical, statistical, anecdotal, expert opinion.\nNominalisation: The rapid expansion of cities has led to… Avoid logical fallacies: ad hominem, straw man, false dilemma, slippery slope. Precision: Insofar as…, to the extent that…'],
      eg: [['Given that demand is rising, it follows that prices will increase.', 'Talab oshayotganini hisobga olsak, narxlar oshishi kelib chiqadi.'], ['Anecdotal evidence alone cannot support such a broad claim.', 'Faqat hikoyaviy dalil bunday keng da’voni qo‘llab-quvvatlay olmaydi.'], ['To the extent that the data are reliable, the conclusion holds.', 'Ma’lumotlar ishonchli ekan, xulosa o‘rinli.'], ['The argument relies on a false dilemma.', 'Dalil soxta tanlovga tayanadi.']],
      w: [['premise', 'asos (premissa)', 'посылка', 'noun', 'The premise of the argument is flawed.', 'Dalilning asosi nuqsonli.', 'ˈpremɪs'], ['warrant', 'asoslovchi bog‘lanish', 'обоснование', 'noun', 'State the warrant explicitly.', 'Asoslovchi bog‘lanishni aniq ko‘rsating.', 'ˈwɒrənt'], ['fallacy', 'mantiqiy xato', 'логическая ошибка', 'noun', 'That is a common fallacy.', 'Bu keng tarqalgan mantiqiy xato.', 'ˈfæləsi'], ['empirical', 'tajribaviy', 'эмпирический', 'adjective', 'Empirical evidence supports the theory.', 'Tajribaviy dalil nazariyani qo‘llab-quvvatlaydi.', 'ɪmˈpɪrɪkl'], ['hence', 'shu sababli', 'следовательно', 'adverb', 'Costs rose; hence prices increased.', 'Xarajatlar oshdi; shu sababli narxlar ko‘tarildi.', 'hens'], ['insofar as', '… darajada', 'постольку поскольку', 'phrase', 'Insofar as the data allow, we conclude this.', 'Ma’lumot imkon bergan darajada shuni xulosa qilamiz.', 'ˌɪnsəʊˈfɑːr æz']],
      g: [['___ that demand is rising, prices will increase.', 'Given', 'Giving', 'Gave', '“Given that” — hisobga olsak.'], ['The argument ___ on a false dilemma.', 'relies', 'rely', 'relying', 'Birlik: relies.']],
      dlg: ['Tutor: Your claim is clear, but where is the warrant? Student: The statistics show a rise in exam scores. Tutor: Yes, but why does that support the claim that homework works? Student: Because the rise follows its introduction. Tutor: That is correlation, not causation. Hence, your conclusion needs a more cautious form.', 'What is the weakness of the student’s argument?', 'It confuses correlation with causation', 'It has no statistics', 'It is too short', 'The tutor says “That is correlation, not causation”.'],
      rd: ['A persuasive argument does more than assert; it demonstrates. The writer presents a claim, supports it with premises and evidence, and explains the warrant that links the evidence to the claim. Weak arguments often fall into fallacies: a straw man misrepresents the opposing view, while a false dilemma presents only two options when more exist. Strong writers also qualify their claims, acknowledging the extent to which the evidence supports them, which makes the argument more credible rather than weaker.', ['Why do strong writers qualify their claims?', 'It makes the argument more credible', 'It makes the text longer', 'It avoids evidence'], ['Weak arguments never use fallacies.', 'False'], ['The text was written by a philosopher.', 'Not Given']],
      wr: ['Write an argument paragraph (150 words) with a claim, premise, evidence, warrant and conclusion on a topic of your choice.', 'given that|it follows that|evidence|insofar as', 110, 'Cities should invest more in public transport. Given that private cars cause most urban pollution, it follows that reducing car use will improve air quality. Statistical evidence from several European cities shows a fall in emissions after the introduction of cheaper buses. Insofar as these results can be generalised, the policy is justified. Hence, municipal budgets should prioritise public transport.'],
      sp: ['Present a claim and two supporting premises in one minute.', 'My claim is that cities need more bike lanes. First, cycling reduces pollution. Second, it improves public health. It follows that bike lanes are a sound investment.'],
      ts: [['A hidden error in reasoning:', 'fallacy', 'premise', 'warrant'], ['“Shu sababli” (formal):', 'hence', 'insofar', 'nearly'], ['It ___ that the policy failed.', 'follows', 'follow', 'following']] },
    { t: ['Counterarguments', 'Qarshi dalillar'],
      obj: ['Qarshi dalillarni adolatli bayon qilib, ularga javob berasiz.', 'You will present counterarguments fairly and respond to them.'],
      ex: ['Qarshi dalil tuzilmasi: concession (tan olish) → rebuttal (rad etish) → reaffirmation (da’voni mustahkamlash). Iboralar: It could be objected that…, Admittedly…, While there is some truth in…, this overlooks…, Nonetheless, …, Even if this were the case, …\nTa’sirchan bog‘lovchilar: notwithstanding (… ga qaramay), albeit (garchi), whereas, conversely (aksincha). Rad etish usullari: question the evidence, challenge the premise, show irrelevance, demonstrate unintended consequences.',  'Counterargument structure: concession → rebuttal → reaffirmation. Phrases: It could be objected that…, Admittedly…, While there is some truth in…, this overlooks…, Nonetheless, …, Even if this were the case, …\nStrong connectors: notwithstanding, albeit, whereas, conversely. Ways to rebut: question the evidence, challenge the premise, show irrelevance, demonstrate unintended consequences.'],
      eg: [['It could be objected that the policy is expensive.', 'Siyosat qimmat deb e’tiroz bildirish mumkin.'], ['Admittedly, costs are high; nonetheless, the benefits are greater.', 'To‘g‘ri, xarajat yuqori; shunga qaramay foyda kattaroq.'], ['Even if this were the case, it would not change the outcome.', 'Hatto shunday bo‘lganda ham, natija o‘zgarmasdi.'], ['Notwithstanding the risks, the project went ahead.', 'Xavflarga qaramay, loyiha davom etdi.']],
      w: [['concede', 'tan olmoq (qisman)', 'признавать', 'verb', 'I concede that the cost is high.', 'Narx yuqori ekanini tan olaman.', 'kənˈsiːd'], ['rebut', 'rad etmoq', 'опровергать', 'verb', 'She rebutted every objection.', 'U har bir e’tirozni rad etdi.', 'rɪˈbʌt'], ['notwithstanding', '… ga qaramay', 'несмотря на', 'preposition', 'Notwithstanding the cost, they built it.', 'Narxga qaramay, ular qurdi.', 'ˌnɒtwɪθˈstændɪŋ'], ['albeit', 'garchi', 'хотя и', 'conjunction', 'A good, albeit expensive, plan.', 'Yaxshi, garchi qimmat bo‘lsa-da, reja.', 'ɔːlˈbiːɪt'], ['conversely', 'aksincha', 'наоборот', 'adverb', 'Conversely, some benefit from it.', 'Aksincha, ba’zilar undan foyda ko‘radi.', 'ˈkɒnvɜːsli'], ['objection', 'e’tiroz', 'возражение', 'noun', 'The main objection is cost.', 'Asosiy e’tiroz — narx.', 'əbˈdʒekʃn']],
      g: [['___ the risks, the project went ahead.', 'Notwithstanding', 'Although', 'Despite of', '“Notwithstanding” + ot.'], ['A good, ___ expensive, plan.', 'albeit', 'albeing', 'although is', '“albeit” + sifat.']],
      dlg: ['Chair: Dr Aliyeva, you propose a sugar tax. Dr Aliyeva: Yes. It could be objected that it hurts low-income families. Chair: That is a serious objection. Dr Aliyeva: Admittedly, but this overlooks the health costs they bear. Notwithstanding the initial burden, the net effect is positive.', 'How does Dr Aliyeva respond to the objection?', 'She says it overlooks health costs', 'She ignores it', 'She withdraws the proposal', 'She says “this overlooks the health costs they bear”.'],
      rd: ['The strength of an academic argument is often judged by how it deals with opposing views. Weaker writers either ignore objections or caricature them. Stronger writers present the best version of the counterargument, concede what is valid, and then explain why their position still holds. This strategy, sometimes called steel-manning, demonstrates intellectual honesty. It also anticipates the reader’s doubts, which makes the final conclusion harder to dismiss.', ['What is “steel-manning”?', 'Presenting the best version of an opposing view', 'Ignoring objections', 'Attacking the opponent'], ['Weak writers always address objections.', 'False'], ['Steel-manning was coined in 1980.', 'Not Given']],
      wr: ['Write a paragraph (150 words) in which you present a counterargument fairly and rebut it.', 'it could be objected|admittedly|nonetheless|overlooks', 110, 'Some people argue that homework should be abolished. It could be objected that this would reduce practice time. Admittedly, regular practice is valuable; nonetheless, this overlooks the fact that quality matters more than quantity. Even if homework were useful for some subjects, it would not justify long assignments that harm sleep. Notwithstanding this objection, a reduction remains the more balanced policy.'],
      sp: ['State an opposing view and respond to it in four sentences.', 'It could be objected that online lessons are less effective. Admittedly, interaction is limited. However, this overlooks their flexibility.'],
      ts: [['To partly accept an opposing point:', 'concede', 'rebut', 'imply'], ['“Aksincha” in English:', 'conversely', 'notwithstanding', 'albeit'], ['Albeit ___, the plan worked.', 'risky', 'riskily', 'risk']] },
    { t: ['Hedging and cautious language', 'Ehtiyotkor til (hedging)'],
      obj: ['Da’volarni ehtiyotkor, ilmiy aniq ifodalash uchun hedging vositalarini qo‘llaysiz.', 'You will use hedging devices to make claims cautious and academically precise.'],
      ex: ['Hedging: modal fe’llar (may, might, could), fe’llar (appear, seem, tend, suggest, indicate), ravishlar (arguably, presumably, apparently, potentially), kvantifikatorlar (a number of, to some extent), tuzilmalar (It would appear that…, There is some evidence to suggest that…, It is possible that…).\nMutlaq tilni yumshatish: “Smoking causes cancer” → “Smoking is strongly associated with an increased risk of cancer.” Boosters (kuchaytirgich): clearly, undoubtedly — ehtiyotkor ishlating. Muvozanat: hedge + booster: This strongly suggests that…',  'Hedging: modals (may, might, could), verbs (appear, seem, tend, suggest, indicate), adverbs (arguably, presumably, apparently, potentially), quantifiers (a number of, to some extent), structures (It would appear that…, There is some evidence to suggest that…, It is possible that…).\nSoftening absolutes: “Smoking causes cancer” → “Smoking is strongly associated with an increased risk of cancer.” Boosters: clearly, undoubtedly — use with care. Balance: hedge + booster: This strongly suggests that…'],
      eg: [['It would appear that the effect is temporary.', 'Ta’sir vaqtinchaga o‘xshaydi.'], ['There is some evidence to suggest that sleep improves memory.', 'Uyqu xotirani yaxshilashini ko‘rsatuvchi ba’zi dalillar bor.'], ['The results arguably reflect a wider trend.', 'Natijalar, ehtimol, kengroq tendensiyani aks ettiradi.'], ['This is potentially a serious risk.', 'Bu potentsial jiddiy xavf.']],
      w: [['arguably', 'ehtimol (dalil qilish mumkin)', 'возможно', 'adverb', 'It is arguably the best result.', 'Bu, ehtimol, eng yaxshi natija.', 'ˈɑːɡjuəbli'], ['presumably', 'taxminan, ehtimol', 'предположительно', 'adverb', 'Presumably, they agreed.', 'Ehtimol, ular rozi bo‘lishdi.', 'prɪˈzjuːməbli'], ['apparent', 'ko‘rinadigan', 'очевидный', 'adjective', 'The apparent cause is stress.', 'Ko‘rinadigan sabab — stress.', 'əˈpærənt'], ['tend', 'moyil bo‘lmoq', 'иметь тенденцию', 'verb', 'Results tend to vary.', 'Natijalar o‘zgarishga moyil.', 'tend'], ['potentially', 'potensial jihatdan', 'потенциально', 'adverb', 'It is potentially dangerous.', 'Bu potentsial xavfli.', 'pəˈtenʃəli'], ['qualify', 'ma’noni cheklamoq', 'уточнять', 'verb', 'Qualify your claim carefully.', 'Da’voingizni ehtiyotkorlik bilan cheklang.', 'ˈkwɒlɪfaɪ']],
      g: [['It ___ that the effect is temporary.', 'would appear', 'appears will', 'would appearing', '“It would appear that…”.'], ['Results ___ to vary.', 'tend', 'tends', 'tending', 'Ko‘plik: tend.']],
      dlg: ['Supervisor: Your draft says that social media destroys concentration. Student: That is what the study shows. Supervisor: It only showed a correlation. Hedge it: “is associated with reduced concentration”. Student: And “may” instead of “will”? Supervisor: Exactly. Cautious language protects your credibility.', 'What does the supervisor recommend?', 'Hedge absolute claims', 'Use stronger language', 'Remove the study', 'She says “Hedge it”.'],
      rd: ['Academic writers rarely make absolute statements. Instead, they qualify claims using hedging devices such as “may”, “tend to” and “there is evidence to suggest”. This is not a sign of weakness: given the complexity of most research questions, absolute claims are usually inaccurate and invite criticism. Hedging is, however, a matter of balance. Too much of it produces vague prose, so effective writers hedge where evidence is limited and use stronger language where it is robust.', ['When should writers use stronger language?', 'Where evidence is robust', 'Always', 'Never'], ['Academic writers prefer absolute statements.', 'False'], ['Hedging is used only in science.', 'Not Given']],
      wr: ['Rewrite 6 absolute claims as hedged academic statements and add 4 new hedged claims on a topic of your choice.', 'may|tend to|appears|suggests', 90, 'Smoking is strongly associated with an increased risk of cancer. Remote work may reduce commuting stress. It would appear that online learning tends to suit self-motivated students. There is some evidence to suggest that sleep improves memory. Social media is potentially distracting.'],
      sp: ['Make a cautious claim about the effect of technology on young people.', 'It would appear that technology may affect concentration, although more research is needed.'],
      ts: [['Hedged form of “It is true”:', 'It would appear to be true', 'It is absolutely true', 'It never lies'], ['“Ehtimol” (formal):', 'presumably', 'certainly', 'never'], ['Findings ___ to vary between groups.', 'tend', 'tends', 'tended to']] },
    { t: ['Persuasive speaking', 'Ishontiruvchi nutq'],
      obj: ['Ishontiruvchi nutqni ritorik vositalar bilan qurasiz va taqdim etasiz.', 'You will structure and deliver persuasive speech with rhetorical devices.'],
      ex: ['Ritorik vositalar: rule of three (uchlik), rhetorical question, anaphora (takrorlash), contrast (antiteza), analogy, emotive appeal (pathos), credibility (ethos), logic (logos). Nutq tuzilmasi: hook → problem → solution → call to action. Ohang: pauses, stress, intonation (ovoz ohangi).\nIboralar: Imagine a world where…; Let me be clear:…; The question is not whether…, but how…; Consider the following… Faol fe’llar: urge, appeal to, call upon, rally.',  'Rhetorical devices: rule of three, rhetorical question, anaphora, contrast, analogy, emotive appeal (pathos), credibility (ethos), logic (logos). Speech structure: hook → problem → solution → call to action. Delivery: pauses, stress, intonation.\nPhrases: Imagine a world where…; Let me be clear:…; The question is not whether…, but how…; Consider the following… Strong verbs: urge, appeal to, call upon, rally.'],
      eg: [['The question is not whether we can afford it, but whether we can afford not to.', 'Savol — biz bunga qurbimiz yetadimi emas, qurbimiz yetmasligi mumkinmi.'], ['Imagine a world where every child can read.', 'Har bir bola o‘qiy oladigan dunyoni tasavvur qiling.'], ['We need courage, commitment and cooperation.', 'Bizga jasorat, sadoqat va hamkorlik kerak.'], ['I call upon you to act today.', 'Sizni bugun harakat qilishga chaqiraman.']],
      w: [['rhetorical', 'ritorik', 'риторический', 'adjective', 'A rhetorical question needs no answer.', 'Ritorik savol javob talab qilmaydi.', 'rɪˈtɒrɪkl'], ['anaphora', 'anafora (takrorlash)', 'анафора', 'noun', 'Anaphora repeats the first words.', 'Anafora birinchi so‘zlarni takrorlaydi.', 'əˈnæfərə'], ['credibility', 'ishonchlilik', 'доверие', 'noun', 'A speaker needs credibility.', 'Notiqda ishonchlilik bo‘lishi kerak.', 'ˌkredəˈbɪləti'], ['rally', 'safarbar qilmoq', 'сплачивать', 'verb', 'She rallied the audience.', 'U tomoshabinlarni safarbar qildi.', 'ˈræli'], ['appeal', 'murojaat qilmoq', 'обращаться', 'verb', 'He appealed to their conscience.', 'U ularning vijdoniga murojaat qildi.', 'əˈpiːl'], ['analogy', 'o‘xshatish', 'аналогия', 'noun', 'He used an analogy to explain it.', 'U tushuntirish uchun o‘xshatish ishlatdi.', 'əˈnælədʒi']],
      g: [['The question is not whether we can afford it, ___ whether we can afford not to.', 'but', 'and', 'or', '“not … but …”.'], ['I call ___ you to act today.', 'upon', 'at', 'in', '“call upon”.']],
      dlg: ['Coach: Your opening is weak. Speaker: What should I do? Coach: Start with a hook. Imagine a world where every child can read. Speaker: Then the problem? Coach: Yes, and use the rule of three. Finish with a call to action: I call upon you to act today.', 'What does the coach recommend for the opening?', 'A hook', 'Statistics', 'An apology', 'She says “Start with a hook”.'],
      rd: ['Aristotle identified three modes of persuasion: ethos, the speaker’s credibility; pathos, the appeal to emotion; and logos, the use of logic. Effective speakers combine all three. They establish credibility through expertise, engage emotions with stories, and support their claims with evidence. Rhetorical devices such as the rule of three, repetition and carefully timed pauses make a message memorable. However, persuasion that relies on emotion alone can be manipulative, so ethical speakers ground their appeals in truth.', ['What is ethos?', 'The speaker’s credibility', 'An appeal to emotion', 'Use of logic'], ['Aristotle identified five modes of persuasion.', 'False'], ['Aristotle was born in Rome.', 'Not Given']],
      wr: ['Write the text of a 2-minute persuasive speech (200 words) on a topic you care about, using a hook, the rule of three and a call to action.', 'imagine|not whether|call upon|we need', 130, 'Imagine a world where every child can read. Today, millions cannot. The question is not whether we can afford to change this, but whether we can afford not to. We need courage, commitment and cooperation. Education is not a luxury; education is not a privilege; education is a right. I call upon you to act today.'],
      sp: ['Deliver a one-minute persuasive opening with a hook and a rhetorical question.', 'Imagine a city without traffic. Is that impossible? I believe it is not, and I will show you how.'],
      ts: [['A question asked for effect, not for an answer:', 'rhetorical question', 'analogy', 'rally'], ['“Ishonchlilik” in English:', 'credibility', 'anaphora', 'appeal'], ['I appeal ___ your sense of justice.', 'to', 'for', 'at']] },
  ], exam: [['Given ___ the data are limited, the result is tentative.', 'that', 'what', 'as of', 'grammar'], ['“Garchi” (formal conjunction):', 'albeit', 'thereby', 'hence', 'vocabulary'], ['It ___ that the effect is short-lived.', 'would appear', 'will appears', 'is appear', 'grammar']] },

  { title: 'Nuance and implication', lessons: [
    { t: ['Connotation', 'Konnotatsiya'],
      obj: ['So‘zlarning denotatsiyasi va konnotatsiyasini farqlab, nozik ma’no tanlaysiz.', 'You will distinguish denotation from connotation and choose words with subtle meaning.'],
      ex: ['Denotatsiya — lug‘aviy ma’no; konnotatsiya — his-tuyg‘u va baho. Bir xil ma’noli so‘zlar: slim (ijobiy) – skinny (salbiy) – thin (neytral); determined (ijobiy) – stubborn (salbiy) – obstinate (kuchli salbiy). Ijobiy / neytral / salbiy konnotatsiya: youthful / young / childish.\nKonnotatsiya muhim: reklama, siyosiy nutq, ommaviy axborot. Tahlil: The word “regime” carries a negative connotation, whereas “government” is neutral. Doimiy ibora: spin (burib talqin qilish), euphemism (yumshatma ibora): “passed away” (o‘ldi).', 'Denotation is the dictionary meaning; connotation is the feeling and judgement attached. Words with similar meanings: slim (positive) – skinny (negative) – thin (neutral); determined (positive) – stubborn (negative) – obstinate (strongly negative). Positive / neutral / negative: youthful / young / childish.\nConnotation matters in advertising, political speech and the media. Analysis: The word “regime” carries a negative connotation, whereas “government” is neutral. Related: spin, euphemism: “passed away” (died).'],
      eg: [['“Skinny” has a more negative connotation than “slim”.', '“Skinny” “slim” ga qaraganda salbiyroq konnotatsiyaga ega.'], ['He is determined, but she calls him stubborn.', 'U qat’iyatli, lekin u uni o‘jar deydi.'], ['“Passed away” is a euphemism for “died”.', '“Passed away” — “died” ning yumshatma shakli.'], ['Politicians often spin bad news.', 'Siyosatchilar yomon yangiliklarni ko‘pincha burib talqin qiladi.']],
      w: [['connotation', 'konnotatsiya', 'коннотация', 'noun', 'The word has a negative connotation.', 'So‘zning salbiy konnotatsiyasi bor.', 'ˌkɒnəˈteɪʃn'], ['denotation', 'denotatsiya (lug‘aviy ma’no)', 'денотация', 'noun', 'The denotation is the literal meaning.', 'Denotatsiya — asl ma’no.', 'ˌdiːnəʊˈteɪʃn'], ['euphemism', 'yumshatma ibora', 'эвфемизм', 'noun', 'A euphemism softens harsh words.', 'Yumshatma ibora qo‘pol so‘zlarni yumshatadi.', 'ˈjuːfəmɪzəm'], ['stubborn', 'o‘jar', 'упрямый', 'adjective', 'He is too stubborn to listen.', 'U quloq solmaydigan darajada o‘jar.', 'ˈstʌbən'], ['spin', 'burib talqin qilmoq', 'искажать подачу', 'verb', 'The press office tried to spin the story.', 'Matbuot xizmati voqeani burib talqin qilmoqchi bo‘ldi.', 'spɪn'], ['neutral', 'betaraf', 'нейтральный', 'adjective', 'Use neutral language in reports.', 'Hisobotlarda betaraf tildan foydalaning.', 'ˈnjuːtrəl']],
      g: [['“Skinny” has a more ___ connotation than “slim”.', 'negative', 'negatively', 'negate', 'Sifat kerak.'], ['“Passed away” is a ___ for “died”.', 'euphemism', 'synonym of', 'euphemistic', 'Yumshatma ibora.']],
      dlg: ['Lecturer: Compare “thrifty” and “stingy”. Student: Both describe someone careful with money. Lecturer: The denotation is similar, but the connotation differs. Student: “Thrifty” is positive and “stingy” is negative. Lecturer: Exactly. Good writers choose words with the right connotation.', 'What differs between “thrifty” and “stingy”?', 'The connotation', 'The denotation', 'The spelling', 'The lecturer says the connotation differs.'],
      rd: ['Words carry more than their dictionary meanings. “Home” suggests warmth and belonging, while “house” is simply a building. Advertisers exploit this by choosing words with positive connotations, such as “natural”, “fresh” and “premium”, while avoiding associations with cost or risk. Politicians also use euphemisms and spin to soften unpopular decisions: “job losses” become “workforce adjustment”. Careful readers therefore look beyond what is literally stated and ask why a particular word was chosen.', ['Why do advertisers choose words like “natural”?', 'For their positive connotations', 'For their length', 'For their price'], ['“House” suggests warmth more than “home”.', 'False'], ['Advertisers are required to avoid connotation.', 'Not Given']],
      wr: ['Choose three pairs of near-synonyms with different connotations and explain the difference (10 sentences).', 'connotation|whereas|more negative|suggests', 80, '“Slim” and “skinny” both describe a thin person, but “skinny” has a more negative connotation. “Determined” suggests admirable persistence, whereas “stubborn” suggests an unwillingness to listen. “Thrifty” is positive, while “stingy” is negative. Choosing the right word is essential for accurate meaning.'],
      sp: ['Explain the difference between two words that mean almost the same but feel different.', '“Thrifty” and “stingy” both describe careful spending, but “thrifty” is positive and “stingy” is negative.'],
      ts: [['The emotional colour of a word:', 'connotation', 'denotation', 'definition'], ['“O‘jar” in English:', 'stubborn', 'neutral', 'thrifty'], ['“Passed away” is a gentle way to say:', 'died', 'travelled', 'slept']] },
    { t: ['Irony and tone', 'Kinoya va ohang'],
      obj: ['Kinoya, sarkazm va muallif ohangini matn va nutqda aniqlaysiz.', 'You will identify irony, sarcasm and the author’s tone in texts and speech.'],
      ex: ['Ohang turlari: formal, informal, ironic, sarcastic, humorous, sombre, detached (betaraf), critical. Kinoya: verbal irony (aytilganning aksi), situational irony (kutilmagan holat), dramatic irony. Sarkazm — tanqidiy kinoya: “Oh, brilliant idea!” (aslida yomon). Belgilar: qarama-qarshi lug‘at, ortiqcha maqtov, intonatsiya.\nTahlil iboralari: The writer’s tone is tongue-in-cheek (hazil aralash); There is a hint of irony in…; The understatement is deliberate. Understatement va hyperbole (bo‘rttirish): “a slight problem” (halokat haqida) vs “I’ve told you a million times”.',  'Tone types: formal, informal, ironic, sarcastic, humorous, sombre, detached, critical. Irony: verbal irony (saying the opposite), situational irony (unexpected outcome), dramatic irony. Sarcasm is critical irony: “Oh, brilliant idea!” (actually bad). Signals: contradictory vocabulary, excessive praise, intonation.\nAnalysis phrases: The writer’s tone is tongue-in-cheek; There is a hint of irony in…; The understatement is deliberate. Understatement and hyperbole: “a slight problem” (about a disaster) vs “I’ve told you a million times”.'],
      eg: [['“Oh, brilliant idea!” she said, rolling her eyes.', '“Voy, ajoyib g‘oya!” dedi u ko‘zlarini aylantirib.'], ['The fire station burned down — a case of situational irony.', 'O‘t o‘chirish stansiyasi yonib ketdi — vaziyatli kinoya.'], ['The writer’s tone is tongue-in-cheek.', 'Yozuvchining ohangi hazil aralash.'], ['“A slight problem” was an understatement.', '“Kichik muammo” — kamsitilgan ifoda edi.']],
      w: [['irony', 'kinoya', 'ирония', 'noun', 'There is irony in the title.', 'Sarlavhada kinoya bor.', 'ˈaɪrəni'], ['sarcasm', 'sarkazm (zaharli kinoya)', 'сарказм', 'noun', 'His sarcasm hurt her.', 'Uning sarkazmi uni xafa qildi.', 'ˈsɑːkæzəm'], ['understatement', 'kamsitib aytish', 'преуменьшение', 'noun', 'That was an understatement.', 'Bu kamsitib aytish edi.', 'ˌʌndəˈsteɪtmənt'], ['hyperbole', 'bo‘rttirish', 'гипербола', 'noun', 'It is pure hyperbole.', 'Bu sof bo‘rttirish.', 'haɪˈpɜːbəli'], ['detached', 'betaraf, sovuqqon', 'отстранённый', 'adjective', 'The tone is detached.', 'Ohang sovuqqon.', 'dɪˈtætʃt'], ['tongue-in-cheek', 'hazil aralash', 'с иронией', 'adjective', 'It was a tongue-in-cheek remark.', 'Bu hazil aralash gap edi.', 'ˌtʌŋ ɪn ˈtʃiːk']],
      g: [['There is a hint ___ irony in the title.', 'of', 'for', 'to', '“a hint of”.'], ['His remark was a deliberate ___.', 'understatement', 'understated of', 'understate', 'Ot kerak.']],
      dlg: ['Tutor: What is the tone of the line “What a delightful traffic jam”? Student: It is sarcastic. Tutor: Why? Student: Because the speaker praises something unpleasant. Tutor: Right. And if it were a mild remark about a terrible disaster? Student: That would be understatement.', 'What is the line “What a delightful traffic jam”?', 'Sarcasm', 'A sincere compliment', 'A fact', 'The student says “sarcastic”.'],
      rd: ['In literature, irony is one of the most powerful tools for conveying a message indirectly. A satirical article may describe a ridiculous policy in a serious tone, leaving readers to recognise the absurdity for themselves. Such writing depends on shared knowledge: readers who miss the irony may take the text literally. Understanding tone therefore requires attention to word choice, context and what is left unsaid, rather than to the surface meaning alone.', ['What does ironic writing depend on?', 'Shared knowledge between writer and reader', 'Long sentences', 'Formal vocabulary'], ['Irony is always easy to recognise.', 'False'], ['Satire was invented in ancient Egypt.', 'Not Given']],
      wr: ['Write a short ironic paragraph (120 words) describing a minor problem as if it were a disaster or vice versa; then label the devices used.', 'understatement|hyperbole|irony|tone', 90, 'The train was only three hours late, and the passengers were, naturally, delighted. A slight misunderstanding about the ticket resulted in my sleeping on the platform. It was, I suppose, a refreshing experience. The tone is tongue-in-cheek, and the irony lies in praising something unpleasant. The phrase “a slight misunderstanding” is an understatement.'],
      sp: ['Say a sentence with irony and explain what makes it ironic.', 'What a wonderful day to forget my umbrella. It is ironic because it is pouring.'],
      ts: [['Saying the opposite of what you mean:', 'verbal irony', 'inference', 'denotation'], ['“Bo‘rttirish” in English:', 'hyperbole', 'understatement', 'sarcasm'], ['The tone is ___, as if he doesn’t care.', 'detached', 'tongue-in-cheek of', 'sombred']] },
    { t: ['Inference in reading', 'O‘qishda xulosa chiqarish'],
      obj: ['Matnda to‘g‘ridan-to‘g‘ri aytilmagan ma’noni xulosa qilasiz.', 'You will infer meaning that is not stated directly in a text.'],
      ex: ['Inference — dalillardan mantiqiy xulosa chiqarish. Strategiya: 1) kalit so‘zlarni toping, 2) kontekstni ko‘ring, 3) muallifning so‘z tanlovini baholang, 4) xulosani matn bilan tasdiqlang. Savollar: What can be inferred…? The writer implies… It is suggested that… Ehtiyotkor: matnda yo‘q narsani qo‘shmang (over-inference).\nTilda: imply (muallif nazarda tutadi) vs infer (o‘quvchi xulosa qiladi). Tipik o‘rinlar: attitude, motive, cause, outcome. Clues: contrast words (yet, nevertheless), qualifiers (hardly, rarely).', 'An inference is a logical conclusion from evidence. Strategy: 1) find key words, 2) read the context, 3) evaluate the writer’s word choice, 4) check the inference against the text. Questions: What can be inferred…? The writer implies… It is suggested that… Be careful not to add what is not in the text (over-inference).\nLanguage: imply (the writer suggests) vs infer (the reader concludes). Typical targets: attitude, motive, cause, outcome. Clues: contrast words (yet, nevertheless), qualifiers (hardly, rarely).'],
      eg: [['The writer implies that the plan was a failure.', 'Yozuvchi rejaning muvaffaqiyatsiz bo‘lganini nazarda tutadi.'], ['From the tone we can infer that he disapproved.', 'Ohangdan uning qarshi ekanini xulosa qilamiz.'], ['Hardly anyone attended, which suggests low interest.', 'Deyarli hech kim kelmadi, bu qiziqish pastligini ko‘rsatadi.'], ['It is suggested that the author felt disappointed.', 'Muallif ko‘ngli qolganini ko‘rsatadi.']],
      w: [['infer', 'xulosa chiqarmoq', 'делать вывод', 'verb', 'We can infer his motive.', 'Uning maqsadini xulosa qilishimiz mumkin.', 'ɪnˈfɜː'], ['imply', 'nazarda tutmoq', 'подразумевать', 'verb', 'The writer implies doubt.', 'Yozuvchi shubhani nazarda tutadi.', 'ɪmˈplaɪ'], ['motive', 'turtki (sabab)', 'мотив', 'noun', 'His motive was unclear.', 'Uning turtkisi noaniq edi.', 'ˈməʊtɪv'], ['hint', 'ishora', 'намёк', 'noun', 'There is a hint of regret.', 'Pushaymonlik ishorasi bor.', 'hɪnt'], ['clue', 'ishora, ko‘rsatkich', 'ключ', 'noun', 'Look for clues in the text.', 'Matndan ko‘rsatkichlarni izlang.', 'kluː'], ['evaluate', 'baholamoq', 'оценивать', 'verb', 'Evaluate the writer’s argument.', 'Muallif dalilini baholang.', 'ɪˈvæljueɪt']],
      g: [['We can ___ his motive from the context.', 'infer', 'imply', 'refer to', 'O‘quvchi xulosa qiladi — infer.'], ['The writer ___ that the plan failed.', 'implies', 'infers', 'implied of', 'Muallif nazarda tutadi — implies.']],
      dlg: ['Teacher: “The committee, after three hours, finally agreed.” What can we infer? Student: That the decision was difficult. Teacher: Which words suggest this? Student: “After three hours” and “finally”. Teacher: Good. Remember not to over-infer: the text doesn’t say they were angry.', 'Which words support the inference?', '“After three hours” and “finally”', '“committee”', '“agreed”', 'The student names these words.'],
      rd: ['Reading between the lines is a crucial skill, especially in exams. Consider the sentence: “Despite repeated warnings, the council postponed the repairs once again.” Although the writer never states an opinion, the phrase “despite repeated warnings” and the word “again” imply criticism. A reader who infers this has understood the attitude of the text, not just its facts. However, inferences must be grounded in evidence; speculation that goes beyond the text is likely to be marked wrong.', ['What does “once again” imply?', 'Criticism of repeated delays', 'Praise for the council', 'A new repair'], ['Inference requires ignoring the text.', 'False'], ['The council is in Samarkand.', 'Not Given']],
      wr: ['Write a short analysis (150 words) of the sentence “After years of promises, the bridge was, at last, partially opened.” — what can be inferred and which words suggest it?', 'implies|can be inferred|suggests|the phrase', 100, 'The sentence implies that the project was seriously delayed. It can be inferred that the writer is critical. The phrase “after years of promises” suggests broken commitments, while “at last” shows impatience. The word “partially” implies that the work is still unfinished. Therefore, the tone is mildly sarcastic rather than celebratory.'],
      sp: ['Read a sentence aloud and explain one thing that can be inferred from it.', '“After three hours, the committee finally agreed.” We can infer that the decision was difficult.'],
      ts: [['The reader draws a conclusion:', 'infers', 'implies', 'hints'], ['“Turtki (sabab)” in English:', 'motive', 'clue', 'hint'], ['The writer ___ that he was disappointed.', 'implies', 'infers', 'implying']] },
    { t: ['Near-synonyms', 'Yaqin ma’nodosh so‘zlar'],
      obj: ['Yaqin ma’nodosh so‘zlar orasidan kontekstga eng mosini tanlaysiz.', 'You will choose the most suitable near-synonym for the context.'],
      ex: ['Yaqin ma’nodoshlar bir xil emas: ular darajasi, uslubi, konnotatsiyasi, kollokatsiyasida farq qiladi. Misollar: big / huge / enormous / vast; look / glance / stare / gaze; walk / stroll / stride / wander; say / state / claim / murmur.\nTanlash mezonlari: 1) daraja (intensity), 2) uslub (formal / informal), 3) konnotatsiya, 4) kollokatsiya (heavy rain, strong tea, ✗ strong rain). Misol: “She glanced at the clock” (qisqa), “She stared at the clock” (uzoq, qattiq), “She gazed at the sea” (sevib, tinch).', 'Near-synonyms are not identical: they differ in degree, register, connotation and collocation. Examples: big / huge / enormous / vast; look / glance / stare / gaze; walk / stroll / stride / wander; say / state / claim / murmur.\nCriteria: 1) intensity, 2) register (formal / informal), 3) connotation, 4) collocation (heavy rain, strong tea, ✗ strong rain). Example: “She glanced at the clock” (briefly), “She stared at the clock” (long and hard), “She gazed at the sea” (fondly, calmly).'],
      eg: [['She glanced at the clock, then stared at the door.', 'U soatga bir qarab oldi, keyin eshikka tikildi.'], ['They strolled along the beach.', 'Ular sohil bo‘ylab sekin sayr qilishdi.'], ['The minister claimed that costs would fall.', 'Vazir xarajatlar kamayishini da’vo qildi.'], ['It was an enormous, vast desert.', 'Bu ulkan, keng cho‘l edi.']],
      w: [['glance', 'bir qarab olmoq', 'взглянуть', 'verb', 'She glanced at her watch.', 'U soatiga bir qarab oldi.', 'ɡlɑːns'], ['stare', 'tikilmoq', 'пристально смотреть', 'verb', 'It is rude to stare.', 'Tikilish qo‘pollik.', 'steə'], ['gaze', 'tikilib mahliyo bo‘lmoq', 'смотреть задумчиво', 'verb', 'He gazed at the stars.', 'U yulduzlarga tikilib qoldi.', 'ɡeɪz'], ['stroll', 'sekin sayr qilmoq', 'прогуливаться', 'verb', 'They strolled by the river.', 'Ular daryo bo‘yida sayr qilishdi.', 'strəʊl'], ['murmur', 'shivirlamoq', 'бормотать', 'verb', 'She murmured a reply.', 'U shivirlab javob berdi.', 'ˈmɜːmə'], ['vast', 'kengaygan, ulkan', 'обширный', 'adjective', 'A vast desert lay ahead.', 'Oldinda ulkan cho‘l yotardi.', 'vɑːst']],
      g: [['She ___ at the clock for a second, then returned to work.', 'glanced', 'stared', 'gazed', 'Qisqa qarash — glanced.'], ['They ___ along the beach after dinner.', 'strolled', 'strode', 'marched', 'Sekin sayr — strolled.']],
      dlg: ['Editor: Your text repeats “said” and “looked”. Writer: Which alternatives do you suggest? Editor: “Murmured” for a quiet voice, “stared” for an intense look. Writer: What about “walked”? Editor: Use “strolled” for a relaxed pace and “strode” for a confident one.', 'Which verb shows a relaxed walk?', 'Strolled', 'Strode', 'Marched', 'The editor says “strolled” for a relaxed pace.'],
      rd: ['Choosing between near-synonyms is one of the clearest signs of advanced vocabulary. In a novel, “she stared at the letter” suggests tension, “she glanced at it” suggests indifference and “she gazed at it” suggests longing. In academic writing, “claim” may suggest doubt, while “demonstrate” suggests proof. Dictionaries show differences in register and collocation, but the most reliable method is to read widely and notice how skilled writers use similar words in different contexts.', ['What is the most reliable method, according to the text?', 'Reading widely and noticing usage', 'Using one word always', 'Avoiding dictionaries'], ['“Claim” and “demonstrate” are exact synonyms.', 'False'], ['Dictionaries list every connotation.', 'Not Given']],
      wr: ['Write a descriptive paragraph (120 words) of a character looking, walking and speaking, choosing precise near-synonyms. Then list your choices with a note on why each fits.', 'glanced|stared|strolled|murmured', 90, 'He strolled into the room and glanced at the clock. When he saw her, he stared in surprise. “You came,” he murmured. She gazed at him for a long moment before replying. Choices: glanced (brief), stared (intense), strolled (relaxed), murmured (quiet), gazed (calm and thoughtful).'],
      sp: ['Describe how someone looks at a view using three different verbs.', 'He glanced at the view, then stared at the mountains and finally gazed at the sea.'],
      ts: [['A quick look:', 'glance', 'gaze', 'stare'], ['“Shivirlamoq” in English:', 'murmur', 'stroll', 'claim'], ['He ___ confidently into the meeting.', 'strode', 'wandered', 'drifted by']] },
  ], exam: [['The writer’s tone is ___; he does not take sides.', 'detached', 'sombred', 'tongue', 'vocabulary'], ['Choose the most formal option:', 'commence', 'start', 'get going', 'vocabulary'], ['From the context we can ___ his motive.', 'infer', 'imply', 'refer', 'grammar']] },

  { title: 'Academic writing', lessons: [
    { t: ['Essay structure', 'Esse tuzilmasi'],
      obj: ['Murakkab akademik essening mantiqiy tuzilmasini quraysiz.', 'You will build the logical structure of a complex academic essay.'],
      ex: ['Akademik esse: Introduction (background, thesis, roadmap), Body (topic sentence, development, evidence, analysis, link), Conclusion (restatement, implications). Tezis: aniq, bahsli, qamrab oluvchi. Paragraf ichi: PEEL / PEAL (Point–Evidence–Analysis–Link). Kohezyon (bog‘liqlik) vositalari: referencing (this, such, the former), substitution, lexical chains, transitions. Kogerensiya — fikrlar mantiqiy ketma-ketligi.\nTuzilmaviy iboralar: This essay will examine…, The first section considers…, Turning to…, With respect to…, Taken together, these findings suggest… Hedging va nominalizatsiya.', 'Academic essay: Introduction (background, thesis, roadmap), Body (topic sentence, development, evidence, analysis, link), Conclusion (restatement, implications). Thesis: clear, arguable, comprehensive. Inside paragraphs: PEEL / PEAL (Point–Evidence–Analysis–Link). Cohesion devices: referencing (this, such, the former), substitution, lexical chains, transitions. Coherence is the logical flow of ideas.\nStructural phrases: This essay will examine…, The first section considers…, Turning to…, With respect to…, Taken together, these findings suggest… Hedging and nominalisation.'],
      eg: [['This essay will examine the causes of urban migration.', 'Bu esse shahar migratsiyasi sabablarini ko‘rib chiqadi.'], ['Turning to the economic dimension, wages play a key role.', 'Iqtisodiy jihatga o‘tsak, maosh muhim rol o‘ynaydi.'], ['Taken together, these findings suggest a clear pattern.', 'Birgalikda bu topilmalar aniq qonuniyatni ko‘rsatadi.'], ['The former argument is stronger than the latter.', 'Birinchi dalil ikkinchisidan kuchliroq.']],
      w: [['thesis statement', 'tezis bayoni', 'тезисное утверждение', 'noun', 'The thesis statement appears in the introduction.', 'Tezis bayoni kirishda keladi.', 'ˈθiːsɪs ˈsteɪtmənt'], ['cohesion', 'bog‘liqlik', 'связность', 'noun', 'Cohesion links sentences.', 'Bog‘liqlik gaplarni bog‘laydi.', 'kəʊˈhiːʒn'], ['coherence', 'izchillik', 'логичность', 'noun', 'Coherence makes ideas flow.', 'Izchillik fikrlarni oqimli qiladi.', 'kəʊˈhɪərəns'], ['roadmap', 'reja (matn yo‘l xaritasi)', 'структура изложения', 'noun', 'Add a roadmap to the introduction.', 'Kirishga yo‘l xaritasini qo‘shing.', 'ˈrəʊdmæp'], ['implication', 'oqibat, ma’no', 'следствие', 'noun', 'The findings have implications for policy.', 'Topilmalar siyosat uchun oqibatlarga ega.', 'ˌɪmplɪˈkeɪʃn'], ['dimension', 'jihat', 'аспект', 'noun', 'Consider the economic dimension.', 'Iqtisodiy jihatni ko‘rib chiqing.', 'daɪˈmenʃn']],
      g: [['___ together, these findings suggest a clear pattern.', 'Taken', 'Taking', 'Take', 'Passiv participle.'], ['The ___ argument is stronger than the latter.', 'former', 'formal', 'first of', 'Former = birinchisi.']],
      dlg: ['Supervisor: Your essay lacks a roadmap. Student: Where should it go? Supervisor: At the end of the introduction. For example: This essay will examine… Student: And within paragraphs? Supervisor: Use PEEL: Point, Evidence, Explanation, Link. Check cohesion and coherence.', 'Where should the roadmap go?', 'At the end of the introduction', 'In the conclusion', 'In the title', 'The supervisor says “At the end of the introduction”.'],
      rd: ['A successful academic essay is built like an argument, not a collection of facts. The introduction provides background, states a thesis and outlines how the essay will proceed. Each body paragraph develops a single idea: it opens with a topic sentence, supplies evidence, analyses its significance and links back to the thesis. The conclusion does not introduce new evidence but synthesises the argument and, where appropriate, points to implications for further research or practice.', ['What does the conclusion do?', 'Synthesises the argument and points to implications', 'Introduces new evidence', 'Repeats the introduction exactly'], ['Each paragraph should develop several unrelated ideas.', 'False'], ['The essay must contain at least ten sources.', 'Not Given']],
      wr: ['Write an introduction (120 words) for an essay on “Remote work and productivity” with background, thesis and roadmap.', 'this essay will|thesis|firstly|turning to', 90, 'Over the past decade, remote work has become common across many sectors. While some studies report increased productivity, others highlight problems of collaboration. This essay will argue that productivity depends less on location than on management practices. It will first examine evidence for productivity gains, then turn to challenges of collaboration, and finally consider implications for employers.'],
      sp: ['Present the structure of an essay you plan to write in four sentences.', 'This essay will examine remote work. First I consider productivity. Then I turn to collaboration. Finally, I discuss implications.'],
      ts: [['Logical flow of ideas:', 'coherence', 'dimension', 'thesis'], ['“Tezis bayoni” in English:', 'thesis statement', 'roadmap', 'implication'], ['Turning ___ the second argument, the data differ.', 'to', 'at', 'with']] },
    { t: ['Paraphrasing and summarising', 'Parafraz va qisqartirib bayon qilish'],
      obj: ['Matnni parafraz va qisqartirib bayon qilishni plagiatsiz bajarasiz.', 'You will paraphrase and summarise texts without plagiarism.'],
      ex: ['Parafraz — asl ma’noni o‘z so‘zlaringiz bilan, deyarli bir xil uzunlikda ifodalash; summary — asosiy fikrlarni qisqa bayon qilish. Usullar: sinonimlar, gap tuzilmasini o‘zgartirish (active ↔ passive), so‘z turini o‘zgartirish (verb → noun), tartibni o‘zgartirish. Plagiat: manbani ko‘rsatmasdan so‘zma-so‘z nusxa olish. Iqtibos: According to Smith (2020), … ; As Brown argues,…\nXatolardan saqlaning: faqat sinonim almashtirish (patchwriting). Tekshirish: ma’no saqlandimi? Uslub o‘zgardimi? Manba ko‘rsatildimi?',  'Paraphrase: restating the original meaning in your own words, at about the same length; summary: stating the main points briefly. Methods: synonyms, changing sentence structure (active ↔ passive), changing word class (verb → noun), reordering. Plagiarism: copying without crediting the source. Citing: According to Smith (2020), … ; As Brown argues,…\nAvoid: only swapping synonyms (patchwriting). Check: is the meaning preserved? Has the structure changed? Is the source credited?'],
      eg: [['According to Smith (2020), urban growth is accelerating.', 'Smitga (2020) ko‘ra, shahar o‘sishi tezlashmoqda.'], ['Urban growth is accelerating → The pace of urbanisation is increasing.', 'Shahar o‘sishi tezlashmoqda → Urbanizatsiya sur’ati oshmoqda.'], ['Plagiarism means presenting others’ ideas as your own.', 'Plagiat — boshqalar g‘oyasini o‘zinikidek ko‘rsatish.'], ['In summary, the author argues that regulation is essential.', 'Xulosa qilib, muallif tartibga solish zarur deb hisoblaydi.']],
      w: [['paraphrase', 'parafraz qilmoq', 'перефразировать', 'verb', 'Paraphrase the second sentence.', 'Ikkinchi gapni parafraz qiling.', 'ˈpærəfreɪz'], ['plagiarism', 'plagiat', 'плагиат', 'noun', 'Plagiarism is a serious offence.', 'Plagiat jiddiy huquqbuzarlik.', 'ˈpleɪdʒərɪzəm'], ['summarise', 'qisqartirib bayon qilmoq', 'обобщать', 'verb', 'Summarise the article in 50 words.', 'Maqolani 50 so‘zda bayon qiling.', 'ˈsʌməraɪz'], ['cite', 'iqtibos keltirmoq', 'цитировать', 'verb', 'Always cite your sources.', 'Manbalaringizni doim ko‘rsating.', 'saɪt'], ['original', 'asl', 'оригинал', 'adjective', 'Keep the original meaning.', 'Asl ma’noni saqlang.', 'əˈrɪdʒənl'], ['rephrase', 'boshqacha ifodalamoq', 'изложить иначе', 'verb', 'Rephrase the sentence.', 'Gapni boshqacha ifodalang.', 'ˌriːˈfreɪz']],
      g: [['___ to Smith (2020), urban growth is accelerating.', 'According', 'Accordingly', 'Accord', '“According to”.'], ['Always ___ your sources.', 'cite', 'sight', 'site', 'Iqtibos keltirmoq — cite.']],
      dlg: ['Lecturer: Paraphrase: “Urban growth is accelerating.” Student: Urbanisation is speeding up. Lecturer: Better to change the structure too: The pace of urbanisation is increasing. Student: Do I need a citation? Lecturer: Yes, according to the author. Otherwise it is plagiarism.', 'Why is a citation required?', 'To avoid plagiarism', 'To lengthen the text', 'To add a synonym', 'The lecturer says “Otherwise it is plagiarism”.'],
      rd: ['Paraphrasing is not simply replacing words with synonyms. Effective paraphrases change both vocabulary and structure while keeping the meaning intact, and they always acknowledge the original source. Summarising requires an additional skill: deciding which points are essential and omitting details. Students who rely on copying phrases, even with a few changes, risk accusations of plagiarism, which most universities treat very seriously. Reading the text, closing it and writing from memory is a recommended technique.', ['What technique is recommended?', 'Reading, closing the text and writing from memory', 'Copying and changing a few words', 'Using translation software only'], ['Replacing words with synonyms is enough.', 'False'], ['Universities forbid summarising.', 'Not Given']],
      wr: ['Paraphrase these two sentences and write a 50-word summary of a paragraph of your choice: “Rapid urbanisation has increased pressure on housing.” “Governments are therefore urged to invest in public transport.”', 'according to|urbanisation|pressure|invest', 70, 'According to the author, the speed of urbanisation is placing greater demands on housing. As a result, authorities are encouraged to spend more on public transport. In summary, the text argues that rapid city growth requires investment in housing and transport.'],
      sp: ['Summarise a short text you have read in two sentences.', 'The article argues that cities need more public transport. It suggests that investment will reduce pollution.'],
      ts: [['Copying without credit is:', 'plagiarism', 'paraphrasing', 'citing'], ['“Parafraz qilmoq” in English:', 'paraphrase', 'cite', 'revise'], ['___ the author, the trend is growing.', 'According to', 'Accord with', 'In accordance']] },
    { t: ['Academic vocabulary', 'Akademik lug‘at'],
      obj: ['Akademik lug‘atni (AWL turidagi) aniq va o‘z o‘rnida ishlatasiz.', 'You will use academic vocabulary (AWL-type) accurately and appropriately.'],
      ex: ['Akademik so‘zlar: analyse, assess, assume, concept, context, derive (kelib chiqmoq), distribute, establish, evidence, factor, framework, interpret, significant, sufficient, undertake. Kollokatsiyalar: conduct research, draw a conclusion, play a role, raise an issue, reach a consensus, carry out an analysis.\nSo‘z oilasi: analyse – analysis – analytical – analytically; significant – significance – significantly. Uslub: informal → formal: get → obtain; show → demonstrate; look at → examine; enough → sufficient; use → utilise.',  'Academic words: analyse, assess, assume, concept, context, derive, distribute, establish, evidence, factor, framework, interpret, significant, sufficient, undertake. Collocations: conduct research, draw a conclusion, play a role, raise an issue, reach a consensus, carry out an analysis.\nWord families: analyse – analysis – analytical – analytically; significant – significance – significantly. Register: informal → formal: get → obtain; show → demonstrate; look at → examine; enough → sufficient; use → utilise.'],
      eg: [['Researchers conducted a detailed analysis.', 'Tadqiqotchilar batafsil tahlil o‘tkazdi.'], ['The concept derives from earlier theories.', 'Tushuncha avvalgi nazariyalardan kelib chiqadi.'], ['Sufficient evidence was established.', 'Yetarli dalil aniqlandi.'], ['The study undertakes a comparison of two methods.', 'Tadqiqot ikki usulni solishtirishni o‘z zimmasiga oladi.']],
      w: [['analyse', 'tahlil qilmoq', 'анализировать', 'verb', 'We analysed the data.', 'Biz ma’lumotni tahlil qildik.', 'ˈænəlaɪz'], ['derive', 'kelib chiqmoq', 'происходить', 'verb', 'The word derives from Latin.', 'So‘z lotin tilidan kelib chiqqan.', 'dɪˈraɪv'], ['sufficient', 'yetarli', 'достаточный', 'adjective', 'There is sufficient evidence.', 'Yetarli dalil bor.', 'səˈfɪʃnt'], ['undertake', 'zimmasiga olmoq', 'предпринимать', 'verb', 'They undertook a study.', 'Ular tadqiqotni zimmasiga oldi.', 'ˌʌndəˈteɪk'], ['framework', 'asos, tizim', 'структура', 'noun', 'The framework guides the study.', 'Asos tadqiqotga yo‘l ko‘rsatadi.', 'ˈfreɪmwɜːk'], ['consensus', 'umumiy kelishuv', 'консенсус', 'noun', 'There is a consensus on the issue.', 'Masalada umumiy kelishuv bor.', 'kənˈsensəs']],
      g: [['The word ___ from Latin.', 'derives', 'derive', 'deriving', 'Birlik.'], ['Researchers ___ a detailed analysis.', 'conducted', 'did to', 'made on', 'Kollokatsiya: conduct an analysis.']],
      dlg: ['Tutor: Replace “look at” and “enough” with formal alternatives. Student: “Examine” and “sufficient”. Tutor: Good. What about “get a result”? Student: “Obtain a result”. Tutor: Excellent. Remember collocations: conduct research, draw a conclusion.', 'What is a formal alternative to “look at”?', 'Examine', 'Get', 'Show', 'The student says “Examine”.'],
      rd: ['Academic vocabulary is the set of words that appear across many university subjects regardless of the discipline. Learners who master about 570 word families can understand a significant proportion of academic texts. However, knowing a word means more than recognising it: students must also know its collocations, its grammar and its register. For instance, “carry out research” and “conduct research” are natural, but “do research” is less formal. Regular reading and word-family notebooks help learners to acquire these patterns.', ['What does knowing a word include?', 'Collocations, grammar and register', 'Only translation', 'Only spelling'], ['Academic vocabulary is subject-specific only.', 'False'], ['The list contains exactly 1,000 words.', 'Not Given']],
      wr: ['Write an academic paragraph (120 words) about a research topic using at least eight academic words from this lesson.', 'conduct|analysis|sufficient|framework', 90, 'Researchers conducted an analysis of how students interpret feedback. The framework used in the study was based on earlier theories. Sufficient evidence was established to draw a conclusion about the role of motivation. Several factors were assessed, and a consensus was reached that clear feedback improves performance.'],
      sp: ['Explain in two formal sentences what a research study found.', 'The study conducted an analysis of student motivation. It concluded that clear feedback plays a significant role.'],
      ts: [['Formal word for “enough”:', 'sufficient', 'significant', 'sudden'], ['“Kelib chiqmoq” in English:', 'derive', 'assess', 'establish'], ['They ___ research on memory.', 'conducted', 'did in', 'made']] },
    { t: ['Formal register and style', 'Rasmiy uslub'],
      obj: ['Matnni norasmiy uslubdan akademik rasmiy uslubga o‘tkazasiz.', 'You will convert text from informal to formal academic style.'],
      ex: ['Rasmiy uslub belgilari: qisqartma yo‘q, phrasal verb o‘rniga formal fe’l (put off → postpone), birinchi shaxs minimal, obyektiv ohang, majhul va nominalizatsiya, aniq raqamlar, emotsional so‘zlar yo‘q. Norasmiy → rasmiy: kids → children, a lot of → a considerable number of, big → substantial, find out → discover, get better → improve.\nSo‘roq gaplardan qoching (rhetorical question akademikda kam). Impersonal tuzilmalar: It can be argued that…, It is evident that…, Evidence suggests… Tinish belgilari: nuqtali vergul, ikki nuqta to‘g‘ri ishlating.',  'Formal features: no contractions, formal verbs instead of phrasal verbs (put off → postpone), minimal first person, objective tone, passive and nominalisation, precise figures, no emotive words. Informal → formal: kids → children, a lot of → a considerable number of, big → substantial, find out → discover, get better → improve.\nAvoid rhetorical questions in academic writing. Impersonal structures: It can be argued that…, It is evident that…, Evidence suggests… Use semicolons and colons correctly.'],
      eg: [['Kids need a lot of sleep → Children require a considerable amount of sleep.', 'Bolalarga ko‘p uyqu kerak → Bolalar sezilarli miqdorda uyqu talab qiladi.'], ['We found out that results got better → It was discovered that results improved.', 'Natijalar yaxshilangani aniqlandi.'], ['It can be argued that the policy is flawed.', 'Siyosat nuqsonli deyish mumkin.'], ['The committee postponed the decision.', 'Qo‘mita qarorni kechiktirdi.']],
      w: [['considerable', 'sezilarli', 'значительный', 'adjective', 'A considerable number of students agreed.', 'Sezilarli sondagi talabalar rozi bo‘ldi.', 'kənˈsɪdərəbl'], ['substantial', 'jiddiy, katta', 'существенный', 'adjective', 'There was a substantial increase.', 'Jiddiy o‘sish bo‘ldi.', 'səbˈstænʃl'], ['postpone', 'kechiktirmoq', 'откладывать', 'verb', 'They postponed the meeting.', 'Ular yig‘ilishni kechiktirdi.', 'pəʊsˈpəʊn'], ['require', 'talab qilmoq', 'требовать', 'verb', 'The task requires patience.', 'Vazifa sabrni talab qiladi.', 'rɪˈkwaɪə'], ['objective', 'xolis', 'объективный', 'adjective', 'Remain objective in reports.', 'Hisobotlarda xolis qoling.', 'əbˈdʒektɪv'], ['evident', 'ravshan', 'очевидный', 'adjective', 'It is evident that costs rose.', 'Xarajatlar oshgani ravshan.', 'ˈevɪdənt']],
      g: [['A ___ number of students agreed.', 'considerable', 'big', 'lot', 'Formal — considerable.'], ['It ___ discovered that results improved.', 'was', 'were', 'had be', 'Majhul.']],
      dlg: ['Tutor: Rewrite “The kids found out it got better.” Student: “Children discovered that it improved.” Tutor: Good. Now remove “we think”. Student: “It can be argued that…”. Tutor: Yes, formal style is impersonal and precise. Avoid contractions as well.', 'What is the formal version of “found out”?', 'Discovered', 'Got', 'Looked at', 'The student says “discovered”.'],
      rd: ['Formal writing differs from speech not only in vocabulary but also in structure. Spoken English favours short clauses and phrasal verbs, whereas academic prose uses longer sentences, nominal groups and precise verbs. For example, “People are more worried about the economy now” becomes “Concern about the economy has increased”. Impersonal constructions (“It is evident that…”) give an objective tone. Nevertheless, formality should not lead to unnecessary complexity: clarity remains the primary aim.', ['What remains the primary aim?', 'Clarity', 'Complexity', 'Length'], ['Spoken English prefers long nominal groups.', 'False'], ['Formal English is taught only at university.', 'Not Given']],
      wr: ['Rewrite this informal paragraph in formal academic style (100–120 words): “Lots of kids don’t get enough sleep these days, and it’s a big problem. Teachers say they can’t concentrate, and exam results get worse.”', 'a considerable number|it is evident|require|as a result', 85, 'A considerable number of children do not obtain sufficient sleep, which constitutes a substantial problem. Teachers report that pupils are unable to concentrate, and as a result examination performance deteriorates. It is evident that adequate rest is essential for academic achievement.'],
      sp: ['Say an informal sentence and convert it to formal style aloud.', 'Kids need a lot of sleep. Children require a considerable amount of sleep.'],
      ts: [['Formal for “get better”:', 'improve', 'enhance up', 'look up'], ['“Ravshan” in English:', 'evident', 'objective', 'substantial'], ['A formal text avoids ___.', 'contractions', 'evidence', 'nouns']] },
  ], exam: [['___ to Smith (2021), the trend is rising.', 'According', 'Accorded', 'Accord', 'grammar'], ['“Plagiat” in English:', 'plagiarism', 'paraphrase', 'cohesion', 'vocabulary'], ['Formal version of “a lot of”:', 'a considerable number of', 'lots of', 'loads', 'vocabulary']] },

  { title: 'Presentations and debates', lessons: [
    { t: ['Presentation structure', 'Taqdimot tuzilmasi'],
      obj: ['Aniq tuzilmali professional taqdimotni rejalashtirasiz va o‘tkazasiz.', 'You will plan and deliver a professionally structured presentation.'],
      ex: ['Tuzilma: Opening (hook, topic, purpose, outline) → Body (signposting, evidence, visuals) → Conclusion (summary, takeaway, Q&A). Signposting: Let me begin by…, Moving on to…, This brings me to…, As you can see from this slide…, To summarise… Vizual: keep slides simple; one idea per slide.\nIshonchli tana tili: eye contact, pace, pauses. Raqamlar: figures show a rise of 12%. Fe’llar: outline, highlight, illustrate, emphasise. Auditoriya bilan aloqa: How many of you have…?',  'Structure: Opening (hook, topic, purpose, outline) → Body (signposting, evidence, visuals) → Conclusion (summary, takeaway, Q&A). Signposting: Let me begin by…, Moving on to…, This brings me to…, As you can see from this slide…, To summarise… Visuals: keep slides simple; one idea per slide.\nConfident delivery: eye contact, pace, pauses. Figures: the figures show a rise of 12%. Verbs: outline, highlight, illustrate, emphasise. Audience contact: How many of you have…?'],
      eg: [['Let me begin by outlining today’s agenda.', 'Bugungi kun tartibini bayon qilishdan boshlayman.'], ['This brings me to my second point.', 'Bu meni ikkinchi fikrga olib keladi.'], ['As you can see from this slide, sales rose by 12%.', 'Bu slaydda ko‘rishingiz mumkin, savdo 12% oshdi.'], ['To summarise, there are three key findings.', 'Xulosa qilib, uchta asosiy topilma bor.']],
      w: [['outline', 'qisqacha bayon qilmoq', 'обрисовать', 'verb', 'I will outline the plan.', 'Men rejani qisqacha bayon qilaman.', 'ˈaʊtlaɪn'], ['highlight', 'ta’kidlamoq', 'выделять', 'verb', 'Let me highlight three points.', 'Uchta fikrni ta’kidlayman.', 'ˈhaɪlaɪt'], ['signpost', 'yo‘nalish ko‘rsatmoq', 'обозначать структуру', 'verb', 'Signpost each section clearly.', 'Har bir bo‘limni aniq ko‘rsating.', 'ˈsaɪnpəʊst'], ['takeaway', 'asosiy xulosa', 'главный вывод', 'noun', 'The key takeaway is simple.', 'Asosiy xulosa oddiy.', 'ˈteɪkəweɪ'], ['audience', 'tomoshabinlar', 'аудитория', 'noun', 'Engage your audience early.', 'Tomoshabinlarni erta jalb qiling.', 'ˈɔːdiəns'], ['slide', 'slayd', 'слайд', 'noun', 'Keep each slide simple.', 'Har bir slaydni oddiy saqlang.', 'slaɪd']],
      g: [['Let me begin ___ outlining today’s agenda.', 'by', 'with to', 'on', '“begin by + -ing”.'], ['As you can ___ from this slide, sales rose.', 'see', 'seen', 'saw', 'can + asosiy fe’l.']],
      dlg: ['Coach: How will you open? Presenter: With a question: How many of you have missed a deadline? Coach: Good hook. Then? Presenter: Let me begin by outlining today’s agenda. Coach: And the end? Presenter: To summarise, with one key takeaway.', 'How does the presenter plan to open?', 'With a question', 'With a joke', 'With statistics', 'He says “With a question”.'],
      rd: ['Effective presentations are built around the audience, not around the speaker’s notes. The best speakers open with a hook that makes listeners want to hear more, then clearly signal the structure of the talk. Throughout, they use signposting phrases so that the audience always knows where they are. Slides should support, not duplicate, the spoken message: one idea per slide with minimal text. Finally, a strong conclusion restates the main message and leaves the audience with a memorable takeaway.', ['What should slides do?', 'Support the spoken message', 'Repeat every word', 'Contain full paragraphs'], ['The best speakers hide the structure.', 'False'], ['Slides must have at least fifty words.', 'Not Given']],
      wr: ['Write the full script for a 3-minute presentation opening and outline (150 words) on a topic of your choice.', 'let me begin|moving on|to summarise|as you can see', 100, 'Good morning, everyone. How many of you have used a language app this week? Today I want to present the results of a short study on mobile learning. Let me begin by outlining the structure. First, I will explain the method. Moving on, I will present the findings. Finally, I will discuss implications. To summarise at the end, I will offer one key takeaway.'],
      sp: ['Give a 1-minute presentation introduction with a hook and an outline.', 'Good morning. How many of you have missed a deadline? Today I will outline three ways to manage time.'],
      ts: [['A phrase that guides the audience:', 'Moving on to…', 'Honestly,', 'You know,'], ['“Tomoshabinlar” in English:', 'audience', 'slide', 'takeaway'], ['Let me ___ the main points.', 'highlight', 'highlights', 'to highlight']] },
    { t: ['Handling questions', 'Savollarga javob berish'],
      obj: ['Qiyin, noaniq yoki dushmanlarcha savollarga professional javob berasiz.', 'You will answer difficult, vague or hostile questions professionally.'],
      ex: ['Strategiya: listen → pause → clarify → answer → check. Iboralar: That’s a fair/good point. Could you clarify what you mean by…? I’m glad you asked that. I don’t have the exact figures at hand, but I can follow up. Let me rephrase the question to make sure I understand. I’d like to come back to that later.\nQiyin savol: Bridging (ko‘prik): That’s an interesting question, and what I’d add is… Shubhali: To the best of my knowledge,… ; As far as I am aware,… Xotirjamlik va hurmat; Savolni umumlashtirish: In other words, you are asking…',  'Strategy: listen → pause → clarify → answer → check. Phrases: That’s a fair/good point. Could you clarify what you mean by…? I’m glad you asked that. I don’t have the exact figures at hand, but I can follow up. Let me rephrase the question to make sure I understand. I’d like to come back to that later.\nDifficult question: Bridging: That’s an interesting question, and what I’d add is… Uncertainty: To the best of my knowledge,… ; As far as I am aware,… Stay calm and respectful; paraphrase: In other words, you are asking…'],
      eg: [['That’s a fair point; let me explain.', 'Bu o‘rinli fikr; tushuntirib beraman.'], ['Could you clarify what you mean by “efficiency”?', '“Samaradorlik” deganda nimani nazarda tutayotganingizni aniqlashtirsangiz?'], ['To the best of my knowledge, no such study exists.', 'Bilishimcha, bunday tadqiqot yo‘q.'], ['I don’t have the figures at hand, but I will follow up.', 'Raqamlar qo‘limda yo‘q, lekin keyinroq aytaman.']],
      w: [['clarify', 'aniqlashtirmoq', 'уточнять', 'verb', 'Could you clarify your point?', 'Fikringizni aniqlashtira olasizmi?', 'ˈklærəfaɪ'], ['rephrase', 'boshqacha ifodalamoq', 'перефразировать', 'verb', 'Let me rephrase the question.', 'Savolni boshqacha ifodalayman.', 'ˌriːˈfreɪz'], ['follow up', 'keyinroq javob bermoq', 'уточнить позже', 'phrasal verb', 'I will follow up by email.', 'Elektron pochta orqali javob beraman.', 'ˈfɒləʊ ʌp'], ['bridge', 'mavzuga ko‘prik qurmoq', 'перейти к теме', 'verb', 'Bridge back to your key message.', 'Asosiy xabaringizga qayting.', 'brɪdʒ'], ['hostile', 'dushmanona', 'враждебный', 'adjective', 'He asked a hostile question.', 'U dushmanona savol berdi.', 'ˈhɒstaɪl'], ['composed', 'xotirjam', 'сдержанный', 'adjective', 'She stayed composed under pressure.', 'U bosim ostida xotirjam qoldi.', 'kəmˈpəʊzd']],
      g: [['To the best of my ___, no such study exists.', 'knowledge', 'known', 'knowing', 'Qat’iy ibora.'], ['I will ___ up by email.', 'follow', 'follows', 'following', 'will + asosiy fe’l.']],
      dlg: ['Audience member: Your figures are completely wrong. Presenter: That’s a fair challenge. Could you clarify which figures you mean? Audience member: The sales numbers on slide five. Presenter: I don’t have the exact data at hand, but I will follow up after the session. Thank you for raising it.', 'How does the presenter respond to the challenge?', 'He clarifies and promises to follow up', 'He ignores it', 'He argues back', 'He asks which figures and promises to follow up.'],
      rd: ['Question-and-answer sessions can be the most difficult part of a presentation, yet they are also an opportunity to show expertise and composure. Experienced speakers listen to the whole question, pause briefly and, if necessary, rephrase it to ensure shared understanding. When they do not know an answer, they say so honestly and offer to follow up, which strengthens credibility. In the case of hostile questions, they remain polite, acknowledge any valid point and bridge back to the key message rather than becoming defensive.', ['What do experts do when they do not know an answer?', 'Say so and offer to follow up', 'Invent an answer', 'Change the subject'], ['They should interrupt hostile questioners.', 'False'], ['Q&A sessions last one hour.', 'Not Given']],
      wr: ['Write a Q&A script (10 lines) in which a presenter answers one clear, one unclear and one hostile question.', 'that’s a fair point|could you clarify|to the best of my knowledge|follow up', 90, 'Q1: What were your main findings? A: Thank you. The main finding was that productivity rose by ten percent. Q2: Your approach is flawed. A: That’s a fair point. Could you clarify which part concerns you? Q3: What about the long term? A: To the best of my knowledge, no data is available yet, but I will follow up.'],
      sp: ['Respond calmly to the statement “Your data seems unreliable.”', 'That is a fair challenge. Could you clarify which data you mean? I would be glad to follow up.'],
      ts: [['To say you don’t know but will find out:', 'I will follow up.', 'I refuse.', 'It’s obvious.'], ['“Aniqlashtirmoq” in English:', 'clarify', 'bridge', 'rephrase'], ['She stayed ___ under pressure.', 'composed', 'compose', 'composing']] },
    { t: ['Debating skills', 'Munozara ko‘nikmalari'],
      obj: ['Rasmiy munozarada o‘z tomoningizni samarali himoya qilasiz.', 'You will argue your side effectively in a formal debate.'],
      ex: ['Rasmiy munozara: proposition (tarafdorlar) va opposition (qarshilar); speaker roles; motion (taklif); burden of proof (isbot yuki); points of information (POI). Nutq tuzilmasi: signpost → argument → evidence → impact (ahamiyat). Iboralar: Point of information, Madam Chair! (qisqa savol), I would like to rebut…, My opponent has failed to address…, The impact of this is…, On the balance of the debate…\nKuchli argument: Claim → Reason → Evidence → Impact (CRE-I). Aniq javob qaytarish: weigh up (taqqoslamoq), outweigh (ustun kelmoq).',  'Formal debate: proposition and opposition; speaker roles; motion; burden of proof; points of information (POI). Speech structure: signpost → argument → evidence → impact. Phrases: Point of information, Madam Chair! (a brief question), I would like to rebut…, My opponent has failed to address…, The impact of this is…, On the balance of the debate…\nStrong argument: Claim → Reason → Evidence → Impact. Weighing: weigh up, outweigh.'],
      eg: [['My opponent has failed to address the cost.', 'Raqibim xarajatni e’tiborga olmadi.'], ['The benefits clearly outweigh the drawbacks.', 'Foyda kamchiliklardan aniq ustun.'], ['The impact of this is that more families will be affected.', 'Buning oqibati — ko‘proq oila zarar ko‘radi.'], ['On the balance of the debate, the motion should fall.', 'Munozara natijasiga ko‘ra, taklif rad etilishi kerak.']],
      w: [['proposition', 'tarafdorlar tomoni', 'сторона утверждения', 'noun', 'The proposition spoke first.', 'Tarafdorlar birinchi so‘zladi.', 'ˌprɒpəˈzɪʃn'], ['opposition', 'qarshi tomon', 'оппозиция', 'noun', 'The opposition rejected the motion.', 'Qarshi tomon taklifni rad etdi.', 'ˌɒpəˈzɪʃn'], ['burden of proof', 'isbot yuki', 'бремя доказывания', 'noun', 'The burden of proof lies with the proposition.', 'Isbot yuki tarafdorlarda.', 'ˈbɜːdn əv pruːf'], ['outweigh', 'ustun kelmoq', 'перевешивать', 'verb', 'The gains outweigh the losses.', 'Foyda zarardan ustun.', 'ˌaʊtˈweɪ'], ['rebuttal', 'rad javobi', 'опровержение', 'noun', 'His rebuttal was precise.', 'Uning rad javobi aniq edi.', 'rɪˈbʌtl'], ['impact', 'ahamiyat, ta’sir', 'значимость', 'noun', 'Explain the impact of your argument.', 'Dalilingiz ta’sirini tushuntiring.', 'ˈɪmpækt']],
      g: [['My opponent has ___ to address the cost.', 'failed', 'fail', 'failing', 'Present Perfect.'], ['The benefits clearly ___ the drawbacks.', 'outweigh', 'overweight', 'out weight', 'Ko‘plik.']],
      dlg: ['Chair: The motion: This house would ban private cars in city centres. Proposition: The impact is cleaner air and safer streets. Opposition: Point of information! Proposition: Not now, thank you. Opposition: My opponent has failed to address the burden on elderly people. On the balance of the debate, the motion should fall.', 'What did the opposition claim?', 'The proposition failed to address elderly people', 'Cars are harmless', 'The motion is perfect', 'They say the burden on elderly people was not addressed.'],
      rd: ['In formal debating, success does not depend on who knows more facts but on who argues more convincingly. Each speaker must advance new arguments, rebut the opposing side and weigh the main points at the end. A strong argument has four parts: a claim, a reason, evidence and an impact that explains why the point matters. Judges reward teams that respond directly to the strongest arguments of their opponents rather than ignoring them, and that show why their own case outweighs the alternatives.', ['What do judges reward?', 'Teams that respond to the strongest opposing arguments', 'The longest speeches', 'The loudest speakers'], ['Success depends only on knowing more facts.', 'False'], ['Debates must last one hour.', 'Not Given']],
      wr: ['Write a 3-minute opening speech (250 words) for the proposition on a motion of your choice with two arguments (claim–reason–evidence–impact).', 'the motion|my first argument|the impact|outweigh', 170, 'Madam Chair, this house believes that universities should be free. My first argument is access. When fees are removed, talented students from poor families can enrol. Evidence from several countries shows higher participation. The impact is a fairer society. My second argument is the economy. Educated graduates earn more and pay higher taxes. The benefits outweigh the costs. We are proud to propose.'],
      sp: ['Rebut an opposing argument in 45 seconds.', 'My opponent claims that the policy is expensive. However, this overlooks long-term savings, which outweigh the initial cost.'],
      ts: [['A short question to the speaker during a debate:', 'point of information', 'rebuttal', 'impact'], ['“Ustun kelmoq” in English:', 'outweigh', 'propose', 'rebut'], ['The ___ of proof lies with the proposition.', 'burden', 'weight', 'cost']] },
    { t: ['Discussion strategies', 'Muhokama strategiyalari'],
      obj: ['Guruh muhokamasini boshqarasiz, ishtirok etasiz va xulosa chiqarasiz.', 'You will manage, contribute to and conclude a group discussion.'],
      ex: ['Muhokama rollari: facilitator, contributor. Iboralar: Boshlash: Shall we start with…? Fikr so‘rash: What’s your take on…? Qo‘shilish: Building on what Ali said,… Qisman rozilik: I’d go along with that to a certain extent, but… E’tiroz: With respect, I see it differently. Xulosa: So, to sum up, we all agree that… Ishtirok etmaganni jalb qilish: Anna, we haven’t heard from you yet.\nKommunikativ strategiyalar: paraphrasing, summarising, turn-taking (navbat), holding the floor (so‘zni ushlab turmoq): Just let me finish this point.',  'Roles: facilitator, contributor. Phrases: Starting: Shall we start with…? Asking opinions: What’s your take on…? Building: Building on what Ali said,… Partial agreement: I’d go along with that to a certain extent, but… Disagreeing: With respect, I see it differently. Concluding: So, to sum up, we all agree that… Including others: Anna, we haven’t heard from you yet.\nStrategies: paraphrasing, summarising, turn-taking, holding the floor: Just let me finish this point.'],
      eg: [['Building on what Ali said, I would add a cost point.', 'Ali aytganiga qo‘shimcha, narx haqida fikr bildiraman.'], ['With respect, I see it differently.', 'Hurmat bilan, men boshqacha qarayman.'], ['Anna, we haven’t heard from you yet.', 'Anna, sizdan hali eshitmadik.'], ['So, to sum up, we all agree that costs are too high.', 'Xulosa: hammamiz xarajat juda yuqori ekaniga qo‘shilamiz.']],
      w: [['facilitate', 'muhokamani boshqarmoq', 'модерировать', 'verb', 'She facilitated the discussion.', 'U muhokamani boshqardi.', 'fəˈsɪlɪteɪt'], ['take', 'nuqtai nazar', 'мнение', 'noun', 'What is your take on this?', 'Bu haqda fikringiz qanday?', 'teɪk'], ['floor', 'so‘z (navbat)', 'слово', 'noun', 'He has the floor.', 'So‘z unda.', 'flɔː'], ['concur', 'rozi bo‘lmoq (rasmiy)', 'соглашаться', 'verb', 'I concur with that view.', 'Men bu fikrga qo‘shilaman.', 'kənˈkɜː'], ['consensus', 'umumiy kelishuv', 'консенсус', 'noun', 'The group reached a consensus.', 'Guruh umumiy kelishuvga erishdi.', 'kənˈsensəs'], ['contribute', 'hissa qo‘shmoq', 'вносить вклад', 'verb', 'Everyone should contribute.', 'Hamma hissa qo‘shishi kerak.', 'kənˈtrɪbjuːt']],
      g: [['___ on what Ali said, I would add a cost point.', 'Building', 'Built', 'Build', 'Participle clause.'], ['With ___, I see it differently.', 'respect', 'respected', 'respecting', '“With respect”.']],
      dlg: ['Facilitator: What’s your take on the proposal? Ali: I think it’s too expensive. Dilnoza: Building on what Ali said, we should compare it with alternatives. Facilitator: Anna, we haven’t heard from you yet. Anna: I’d go along with that to a certain extent, but cost isn’t everything. Facilitator: So, to sum up, we all agree to compare options.', 'What does the facilitator do at the end?', 'Sums up the agreement', 'Starts a new topic', 'Ends the meeting angrily', 'The facilitator says “to sum up”.'],
      rd: ['Productive discussions do not happen by accident. In a successful group, one person facilitates, making sure that everyone has the chance to speak and that the conversation stays on topic. Participants build on each other’s ideas instead of simply stating their own, and they disagree politely by acknowledging valid points first. At the end, a clear summary helps the group to confirm what has been agreed and what remains open, which prevents later misunderstandings.', ['Why is a final summary useful?', 'It confirms what has been agreed', 'It starts an argument', 'It lengthens the meeting'], ['In successful discussions everyone talks at once.', 'False'], ['Facilitators are paid more.', 'Not Given']],
      wr: ['Write a short group discussion (12 lines) among four people deciding where to hold a school trip; include building, disagreeing politely, including a quiet person and summarising.', 'building on|with respect|we haven’t heard|to sum up', 100, 'A: Shall we start with the destination? B: Building on the budget, I suggest the museum. C: With respect, I see it differently; the park is cheaper. A: Anna, we haven’t heard from you yet. D: I’d go along with the park to a certain extent. A: So, to sum up, we choose the park for cost, and add a short museum visit.'],
      sp: ['Take part in an imagined discussion: build on a point and disagree politely.', 'Building on your point, I would add that cost matters. With respect, I see it differently on timing.'],
      ts: [['To invite a quiet person to speak:', 'We haven’t heard from you yet.', 'Be quiet.', 'I disagree.'], ['“Hissa qo‘shmoq” in English:', 'contribute', 'concur', 'facilitate'], ['With respect, I ___ it differently.', 'see', 'seeing', 'saw to']] },
  ], exam: [['Let me begin ___ outlining the agenda.', 'by', 'with', 'on', 'grammar'], ['The advantages of the plan ___ its costs.', 'outweigh', 'overweight', 'underweigh', 'grammar'], ['A short formal question during a speech:', 'point of information', 'takeaway', 'slide', 'vocabulary']] },

  { title: 'Research and data', lessons: [
    { t: ['Describing data', 'Ma’lumotlarni tasvirlash'],
      obj: ['Grafik, jadval va diagramma ma’lumotlarini aniq va ixcham tasvirlaysiz.', 'You will describe data from graphs, tables and charts precisely and concisely.'],
      ex: ['Tendensiya: rise sharply / steadily / marginally, fall dramatically, plateau (barqarorlashmoq), fluctuate, peak at, bottom out at. Taqqoslash: twice as high as, considerably lower than, roughly equal to. Kasr va ulush: a quarter, 40 per cent, the majority, a small minority, approximately one in five.\nTuzilma: The graph illustrates…, As can be seen from the table,…, It is evident that…, By contrast,… Vaqt: between 2010 and 2020, over the period, by the end of. Majhul va nominal: There was a sharp rise in unemployment (vs Unemployment rose sharply).',  'Trends: rise sharply / steadily / marginally, fall dramatically, plateau, fluctuate, peak at, bottom out at. Comparison: twice as high as, considerably lower than, roughly equal to. Proportion: a quarter, 40 per cent, the majority, a small minority, approximately one in five.\nStructures: The graph illustrates…, As can be seen from the table,…, It is evident that…, By contrast,… Time: between 2010 and 2020, over the period, by the end of. Noun form: There was a sharp rise in unemployment (vs Unemployment rose sharply).'],
      eg: [['Sales peaked at 5 million in 2018.', 'Savdo 2018-yilda 5 millionda cho‘qqiga chiqdi.'], ['Unemployment fell dramatically between 2010 and 2015.', 'Ishsizlik 2010–2015 yillar orasida keskin kamaydi.'], ['Approximately one in five students dropped out.', 'Taxminan har besh talabadan biri o‘qishni tashladi.'], ['By contrast, exports remained stable.', 'Aksincha, eksport barqaror qoldi.']],
      w: [['plateau', 'barqaror bo‘lib qolmoq', 'выходить на плато', 'verb', 'Prices plateaued in 2019.', 'Narxlar 2019-yilda barqaror bo‘lib qoldi.', 'ˈplætəʊ'], ['fluctuate', 'tebranmoq', 'колебаться', 'verb', 'Rates fluctuated wildly.', 'Stavkalar keskin tebrandi.', 'ˈflʌktʃueɪt'], ['marginal', 'ahamiyatsiz kichik', 'незначительный', 'adjective', 'There was a marginal increase.', 'Ahamiyatsiz kichik o‘sish bo‘ldi.', 'ˈmɑːdʒɪnl'], ['dramatic', 'keskin', 'резкий', 'adjective', 'A dramatic fall occurred.', 'Keskin pasayish yuz berdi.', 'drəˈmætɪk'], ['proportion', 'ulush', 'доля', 'noun', 'A small proportion agreed.', 'Kichik ulush rozi bo‘ldi.', 'prəˈpɔːʃn'], ['trend', 'tendensiya', 'тенденция', 'noun', 'The trend is upward.', 'Tendensiya yuqoriga.', 'trend']],
      g: [['Sales ___ at 5 million in 2018.', 'peaked', 'peaking', 'peak to', 'O‘tgan zamon.'], ['There was a sharp ___ in unemployment.', 'rise', 'rose', 'rising of', 'Ot kerak.']],
      dlg: ['Lecturer: Look at the graph. How would you describe the trend? Student: Prices rose steadily until 2015, then plateaued. Lecturer: And exports? Student: They fluctuated, peaking at 8 million in 2018. Lecturer: Good. Add a comparison: roughly twice as high as imports.', 'What happened to prices after 2015?', 'They plateaued', 'They fell', 'They doubled', 'The student says “then plateaued”.'],
      rd: ['The table shows the percentage of households with internet access in four countries between 2000 and 2020. In all four countries, access rose dramatically over the period. Country A started at only 5 per cent but reached 90 per cent by 2020, while Country D, which began with the highest figure of 40 per cent, increased more slowly to 85 per cent. By contrast, Country C experienced a marginal decline in 2010 before recovering. Overall, the gap between countries narrowed considerably.', ['Which country started with the highest figure?', 'Country D', 'Country A', 'Country C'], ['Access fell in all four countries.', 'False'], ['Country B had the highest final figure.', 'Not Given']],
      wr: ['Describe the data: Internet use (%) 2010: 30, 2012: 45, 2014: 62, 2016: 75, 2018: 78, 2020: 79. Write 150 words, with an overview and key details.', 'rose|plateau|overall|between', 100, 'The graph illustrates the percentage of people using the internet between 2010 and 2020. Overall, usage rose considerably over the period. It increased sharply from 30 per cent in 2010 to 75 per cent in 2016. After that, the rise slowed, and the figure plateaued at around 79 per cent by 2020. The most dramatic growth occurred between 2012 and 2014.'],
      sp: ['Describe a trend you know (prices, temperatures, users) in four sentences.', 'The number of users rose sharply between 2015 and 2018. Then it plateaued. Overall, the trend is upward.'],
      ts: [['To stay at the same level:', 'plateau', 'fluctuate', 'peak'], ['“Tendensiya” in English:', 'trend', 'proportion', 'margin'], ['A ___ fall in sales surprised everyone.', 'dramatic', 'dramatically', 'drama']] },
    { t: ['Methods and results', 'Usullar va natijalar'],
      obj: ['Tadqiqot usullari va natijalarini akademik uslubda tasvirlaysiz.', 'You will describe research methods and results in academic style.'],
      ex: ['Metodologiya: sample (tanlanma), participants, questionnaire (so‘rovnoma), interview, experiment, control group (nazorat guruhi), variable (o‘zgaruvchi), qualitative vs quantitative, random. Majhul o‘tgan zamon: Participants were asked to…, Data were collected over six weeks, The results were analysed using SPSS. Natijalar: The findings revealed that…, A statistically significant difference was found between…\nBog‘lovchilar: whereas, in contrast, consistent with (… ga mos), contrary to expectations. Cheklovlar: One limitation of the study is that the sample was small.',  'Methodology: sample, participants, questionnaire, interview, experiment, control group, variable, qualitative vs quantitative, random. Passive past: Participants were asked to…, Data were collected over six weeks, The results were analysed using SPSS. Results: The findings revealed that…, A statistically significant difference was found between…\nLinkers: whereas, in contrast, consistent with, contrary to expectations. Limitations: One limitation of the study is that the sample was small.'],
      eg: [['Participants were asked to complete a questionnaire.', 'Ishtirokchilardan so‘rovnomani to‘ldirish so‘ralgan.'], ['Data were collected over six weeks.', 'Ma’lumotlar olti hafta davomida yig‘ildi.'], ['A statistically significant difference was found.', 'Statistik jihatdan sezilarli farq aniqlandi.'], ['One limitation is that the sample was small.', 'Bitta cheklov — tanlanma kichik edi.']],
      w: [['sample', 'tanlanma', 'выборка', 'noun', 'The sample included 200 students.', 'Tanlanmada 200 talaba bor edi.', 'ˈsɑːmpl'], ['variable', 'o‘zgaruvchi', 'переменная', 'noun', 'Control the key variable.', 'Asosiy o‘zgaruvchini nazorat qiling.', 'ˈveəriəbl'], ['control group', 'nazorat guruhi', 'контрольная группа', 'noun', 'The control group received no treatment.', 'Nazorat guruhi davolanmadi.', 'kənˈtrəʊl ɡruːp'], ['quantitative', 'miqdoriy', 'количественный', 'adjective', 'Quantitative data use numbers.', 'Miqdoriy ma’lumotlar raqamlardan iborat.', 'ˈkwɒntɪtətɪv'], ['qualitative', 'sifatiy', 'качественный', 'adjective', 'Qualitative data come from interviews.', 'Sifatiy ma’lumotlar suhbatlardan olinadi.', 'ˈkwɒlɪtətɪv'], ['limitation', 'cheklov', 'ограничение', 'noun', 'Every study has limitations.', 'Har bir tadqiqotda cheklovlar bor.', 'ˌlɪmɪˈteɪʃn']],
      g: [['Data ___ collected over six weeks.', 'were', 'was', 'is', 'Ma’lumotlar (data) — ko‘plik majhul.'], ['A statistically significant difference ___ found.', 'was', 'were', 'is being', 'Majhul.']],
      dlg: ['Examiner: Describe your method. Student: A sample of 200 students was surveyed using a questionnaire. Examiner: Was there a control group? Student: Yes, and the variable was study time. Examiner: What are the limitations? Student: The sample was drawn from one university only.', 'What is the limitation mentioned?', 'The sample came from one university', 'No questionnaire', 'No results', 'The student says so.'],
      rd: ['Methods: A sample of 120 undergraduates was randomly assigned to two groups. The experimental group used spaced repetition for four weeks, whereas the control group revised in the usual way. Data were collected through weekly vocabulary tests and analysed quantitatively. Results: A statistically significant difference was found between the groups, with the experimental group scoring on average 18 per cent higher. Limitations: The study was conducted at a single university, so the results may not be generalisable.', ['How was the sample assigned?', 'Randomly to two groups', 'By teachers’ choice', 'By age'], ['The control group used spaced repetition.', 'False'], ['The study was funded by a company.', 'Not Given']],
      wr: ['Write a methods-and-results paragraph (150 words) for an imagined study on sleep and exam performance.', 'participants were|data were|a significant difference|limitation', 100, 'A sample of 100 students was surveyed over four weeks. Participants were asked to record their sleep and complete a weekly test. Data were analysed quantitatively. A statistically significant difference was found between students who slept eight hours and those who slept less than six. One limitation is that the sample was drawn from one university.'],
      sp: ['Explain how you would test whether a new teaching method works.', 'I would divide a sample into two groups. One group would use the new method, and the other would be a control group.'],
      ts: [['A group that does not receive the treatment:', 'control group', 'sample', 'variable'], ['“Cheklov” in English:', 'limitation', 'variable', 'sample'], ['Participants ___ asked to complete a form.', 'were', 'was', 'be']] },
    { t: ['Evaluating sources', 'Manbalarni baholash'],
      obj: ['Manbalarning ishonchliligi, xolisligi va dolzarbligini baholaysiz.', 'You will assess the reliability, bias and currency of sources.'],
      ex: ['Mezonlar (CRAAP): Currency (dolzarblik), Relevance, Authority (mualliflik vakolati), Accuracy, Purpose. Manba turlari: primary (birlamchi) vs secondary (ikkilamchi), peer-reviewed (ekspert baholagan), grey literature, opinion piece. Belgilar: author credentials, citations, methodology, funding (moliyalashtirish) and conflict of interest.\nBaholash iboralari: The source appears credible because…, This study is limited by…, Given the author’s affiliation, bias cannot be ruled out (istisno qilib bo‘lmaydi). Qiyos: more reliable than, less rigorous than.',  'Criteria (CRAAP): Currency, Relevance, Authority, Accuracy, Purpose. Source types: primary vs secondary, peer-reviewed, grey literature, opinion piece. Signals: author credentials, citations, methodology, funding and conflict of interest.\nEvaluation phrases: The source appears credible because…, This study is limited by…, Given the author’s affiliation, bias cannot be ruled out. Comparison: more reliable than, less rigorous than.'],
      eg: [['The source appears credible because it is peer-reviewed.', 'Manba ishonchli ko‘rinadi, chunki ekspertlar baholagan.'], ['Given the author’s affiliation, bias cannot be ruled out.', 'Muallifning tashkilotiga ko‘ra, xolislik yo‘qligini istisno qilib bo‘lmaydi.'], ['This study is limited by its small sample.', 'Bu tadqiqot kichik tanlanma bilan cheklangan.'], ['A blog post is less rigorous than a journal article.', 'Blog yozuvi jurnal maqolasiga qaraganda kamroq puxta.']],
      w: [['credible', 'ishonchli', 'заслуживающий доверия', 'adjective', 'This is a credible source.', 'Bu ishonchli manba.', 'ˈkredəbl'], ['peer-reviewed', 'ekspertlar baholagan', 'рецензируемый', 'adjective', 'Use peer-reviewed journals.', 'Ekspertlar baholagan jurnallardan foydalaning.', 'pɪə rɪˈvjuːd'], ['rigorous', 'puxta, qat’iy', 'строгий', 'adjective', 'The method is rigorous.', 'Usul puxta.', 'ˈrɪɡərəs'], ['affiliation', 'tashkilotga a’zolik', 'принадлежность', 'noun', 'State the author’s affiliation.', 'Muallifning tashkilotini ko‘rsating.', 'əˌfɪliˈeɪʃn'], ['bias', 'xolislik yo‘qligi', 'предвзятость', 'noun', 'Check the source for bias.', 'Manbada xolislik yo‘qligini tekshiring.', 'ˈbaɪəs'], ['currency', 'dolzarblik (yangilik)', 'актуальность', 'noun', 'Check the currency of the data.', 'Ma’lumotlarning dolzarbligini tekshiring.', 'ˈkʌrənsi']],
      g: [['The source appears credible ___ it is peer-reviewed.', 'because', 'despite', 'unless', 'Sabab.'], ['Bias cannot be ruled ___.', 'out', 'off', 'up', '“rule out”.']],
      dlg: ['Tutor: Is this website a reliable source? Student: It has no author and no references. Tutor: What about the date? Student: It is ten years old, so currency is a problem. Tutor: Right. A peer-reviewed article would be more rigorous.', 'Why is the website unreliable?', 'No author, no references and outdated', 'It is too long', 'It is expensive', 'The student lists these reasons.'],
      rd: ['Not all information is equally trustworthy, and students must learn to evaluate sources critically. Peer-reviewed journals are generally more reliable because experts check the methodology before publication. Websites and blogs vary widely: some are authoritative, while others promote a commercial or political agenda. When assessing a source, researchers ask who wrote it, why, when, and what evidence it provides. They also look for conflicts of interest, such as a study on sugar funded by a drinks company.', ['Why are peer-reviewed journals more reliable?', 'Experts check the methodology before publication', 'They are shorter', 'They are cheaper'], ['All websites are equally reliable.', 'False'], ['Journals charge no fee.', 'Not Given']],
      wr: ['Evaluate two imaginary sources on the same topic (150 words): one peer-reviewed article and one blog. Use credibility language.', 'appears credible|bias|more reliable|currency', 100, 'The peer-reviewed article appears credible because it describes its methodology and was published recently. The blog, by contrast, gives no references, so its reliability is limited. Given the author’s commercial affiliation, bias cannot be ruled out. Overall, the article is more rigorous and should be preferred.'],
      sp: ['Tell how you check whether a website is reliable.', 'I check the author, the date and the references. If there is a conflict of interest, I look for another source.'],
      ts: [['Checked by experts before publication:', 'peer-reviewed', 'primary', 'currency'], ['“Puxta” in English:', 'rigorous', 'credible', 'marginal'], ['Check the ___ of the data.', 'currency', 'currencies of', 'currently']] },
    { t: ['Writing a report', 'Hisobot yozish'],
      obj: ['Tadqiqot yoki muammo bo‘yicha to‘liq rasmiy hisobot yozasiz.', 'You will write a complete formal report on a study or problem.'],
      ex: ['Hisobot bo‘limlari: Title, Executive summary (qisqa mazmun), Introduction, Methodology, Findings, Discussion, Conclusion, Recommendations, References, Appendices. Uslub: rasmiy, bo‘limlar sarlavhali, raqamlangan, jadval va grafiklar manbalari bilan. Iboralar: This report aims to…, The findings indicate…, It can be concluded that…, It is recommended that + asosiy shakl.\nTavsiyalar: prioritise (ustuvor qilmoq), implement, evaluate, monitor. Vizualni izohlash: Figure 1 shows…, Table 2 summarises…',  'Report sections: Title, Executive summary, Introduction, Methodology, Findings, Discussion, Conclusion, Recommendations, References, Appendices. Style: formal, headed and numbered sections, tables and graphs with sources. Phrases: This report aims to…, The findings indicate…, It can be concluded that…, It is recommended that + base verb.\nRecommendations: prioritise, implement, evaluate, monitor. Referring to visuals: Figure 1 shows…, Table 2 summarises…'],
      eg: [['This report aims to assess student satisfaction.', 'Bu hisobot talabalar mamnunligini baholashga qaratilgan.'], ['Figure 1 shows the distribution of responses.', '1-rasm javoblar taqsimotini ko‘rsatadi.'], ['It can be concluded that online support is insufficient.', 'Onlayn yordam yetarli emas, degan xulosa chiqarish mumkin.'], ['It is recommended that the university extend library hours.', 'Universitet kutubxona ish vaqtini uzaytirishi tavsiya etiladi.']],
      w: [['executive summary', 'qisqa mazmun (rahbarlar uchun)', 'резюме', 'noun', 'Read the executive summary first.', 'Avval qisqa mazmunni o‘qing.', 'ɪɡˈzekjətɪv ˈsʌməri'], ['methodology', 'metodologiya', 'методология', 'noun', 'The methodology is explained in Section 2.', 'Metodologiya 2-bo‘limda tushuntirilgan.', 'ˌmeθəˈdɒlədʒi'], ['appendix', 'ilova', 'приложение', 'noun', 'The full data are in the appendix.', 'To‘liq ma’lumot ilovada.', 'əˈpendɪks'], ['prioritise', 'ustuvor qilmoq', 'приоритизировать', 'verb', 'Prioritise the urgent actions.', 'Shoshilinch ishlarni ustuvor qiling.', 'praɪˈɒrətaɪz'], ['monitor', 'kuzatib bormoq', 'отслеживать', 'verb', 'Monitor progress regularly.', 'Taraqqiyotni muntazam kuzatib boring.', 'ˈmɒnɪtə'], ['discussion', 'muhokama (bo‘lim)', 'обсуждение', 'noun', 'The discussion interprets the findings.', 'Muhokama topilmalarni sharhlaydi.', 'dɪˈskʌʃn']],
      g: [['It is recommended that the university ___ library hours.', 'extend', 'extends', 'extended', 'Taklif: that + asosiy shakl.'], ['Figure 1 ___ the distribution of responses.', 'shows', 'show', 'showing', 'Birlik.']],
      dlg: ['Manager: Is the report ready? Analyst: The executive summary and findings are done. Manager: What are the recommendations? Analyst: It is recommended that the company prioritise training and monitor results quarterly. Manager: Put the raw data in an appendix.', 'Where should the raw data go?', 'In an appendix', 'In the title', 'In the conclusion', 'The manager says “in an appendix”.'],
      rd: ['Report: Student Satisfaction, Library Services. Executive summary: This report aims to assess satisfaction with library services among undergraduates. A survey of 250 students was conducted in March. The findings indicate that 68 per cent are satisfied with opening hours, whereas only 41 per cent are satisfied with study space. It can be concluded that capacity during exam periods is insufficient. It is recommended that the university provide additional study areas and extend hours before examinations.', ['What is recommended?', 'Additional study areas and longer hours before exams', 'Closing the library', 'Raising fees'], ['Most students are dissatisfied with opening hours.', 'False'], ['The survey was conducted online.', 'Not Given']],
      wr: ['Write a short formal report (250 words) on a topic of your choice: executive summary, findings with two figures, conclusion and two recommendations.', 'this report aims|the findings indicate|it can be concluded|it is recommended', 170, 'Executive summary: This report aims to assess how students use the internet for study. A survey of 150 students was conducted. The findings indicate that 82 per cent use online resources daily, whereas 18 per cent use them rarely. It can be concluded that online resources are an essential part of study. It is recommended that the university improve Wi-Fi coverage and provide training on evaluating sources.'],
      sp: ['Present the main conclusion and one recommendation of a report in three sentences.', 'The findings indicate that the library is overcrowded. It can be concluded that capacity is insufficient. It is recommended that the university provide more study space.'],
      ts: [['The short overview at the start of a report:', 'executive summary', 'appendix', 'reference'], ['“Ilova” in English:', 'appendix', 'discussion', 'monitor'], ['It is recommended that he ___ a plan.', 'prepare', 'prepares', 'prepared']] },
  ], exam: [['Data ___ collected in two phases.', 'were', 'was', 'is', 'grammar'], ['It is recommended that the firm ___ training.', 'provide', 'provides', 'provided', 'grammar'], ['Numbers-based data are called ___ data.', 'quantitative', 'qualitative', 'primary', 'vocabulary']] },
];
